    position: relative;
    overflow: hidden;
  }

  /* Bottom-right HUD bracket on panel */
  .tab-panels::after {
    content: '';
    position: absolute;
    bottom: -1px;
    right: -1px;
    width: 14px;
    height: 14px;
    border-bottom: 2px solid var(--ne-pink);
    border-right: 2px solid var(--ne-pink);
    border-radius: 0 0 var(--ne-radius) 0;
  }

  .tab-panel {
