    padding: 2rem 2.25rem;
    animation: fade-in 0.3s ease;
  }

  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(6px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .tab-panel.active {
    display: block;
  }

  .tp-heading {
    font-family: var(--ne-font-pixel);
    font-size: 0.6rem;
