    animation: blink-dot 1s step-end infinite;
  }

  .tp-body {
    font-family: var(--ne-font-mono);
    font-size: 0.88rem;
    color: var(--ne-text);
    line-height: 1.9;
    letter-spacing: 0.3px;
  }

  .tp-body p {
    margin-bottom: 1rem;
  }

  .tp-body p:last-child {
    margin-bottom: 0;
  }

  /* Lista neuro */
  .ne-list {
    list-style: none;
    padding: 0;
    margin: 1rem 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .ne-list li {
    font-family: var(--ne-font-mono);
    font-size: 0.86rem;
