<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
const REGIONS = [{"name": "Lobulo Frontal", "desc": "Controla la toma de decisiones, emociones, personalidad y autocontrol.", "hex": "#4d88ff"}, {"name": "Lobulo Parietal", "desc": "Procesa informaci\u00f3n sensorial: tacto, temperatura y orientaci\u00f3n espacial.", "hex": "#44dd88"}, {"name": "Lobulo Occipital", "desc": "Interpreta todo lo que vemos: colores, formas y movimiento visual.", "hex": "#bb55ff"}, {"name": "Lobulo Temporal", "desc": "Procesa el lenguaje, la memoria auditiva y el reconocimiento de objetos.", "hex": "#ffcc33"}, {"name": "Cerebelo", "desc": "Coordina el movimiento y el equilibrio. Controla la precisi\u00f3n motora.", "hex": "#ff7733"}, {"name": "Tronco Encef\u00e1lico", "desc": "Regula funciones vitales: respiraci\u00f3n, ritmo card\u00edaco y ciclos de sue\u00f1o.", "hex": "#ff4477"}];
const MARKERS = [[0.4, 0.5, 0.75], [-0.05, 0.75, 0.1], [-0.7, 0.3, -0.5], [0.7, -0.1, 0.3], [-0.4, -0.55, -0.3], [0.05, -0.75, 0.1]];
const REGION_B64 = ["", "", "", "", "", ""];

// Decode float32 arrays from base64
function decodeF32(b64){
  const bin=atob(b64), buf=new ArrayBuffer(bin.length), view=new Uint8Array(buf);
  for(let i=0;i<bin.length;i++) view[i]=bin.charCodeAt(i);
  return new Float32Array(buf);
}

const canvas=document.getElementById('c');
const app=document.getElementById('app');
let W=app.clientWidth, H=app.clientHeight;

const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
renderer.setSize(W,H);
renderer.setClearColor(0x0a0a16,1);

const scene=new THREE.Scene();
const camera=new THREE.PerspectiveCamera(42,W/H,0.01,100);
camera.position.set(0,0,3.8);

scene.add(new THREE.AmbientLight(0xffffff,0.5));
const d1=new THREE.DirectionalLight(0xffffff,1.0); d1.position.set(2,3,4); scene.add(d1);
const d2=new THREE.DirectionalLight(0x8899ff,0.35); d2.position.set(-3,-1,-2); scene.add(d2);
const pt=new THREE.PointLight(0xffffff,0.4,20); pt.position.set(1,2,2); scene.add(pt);

const brainGroup=new THREE.Group();
scene.add(brainGroup);

// Base colors (dim) and active colors
const BASE_HEX  = [0x1a2444, 0x112a1e, 0x251135, 0x2a2210, 0x2a1808, 0x2a0d18];
const ACTIVE_HEX= [0x4d88ff, 0x44dd88, 0xbb55ff, 0xffcc33, 0xff7733, 0xff4477];

// Hover + active state tracking
let hoveredRegion=-1;
const HOVER_HEX=[0x2a3f7a,0x1a4a30,0x3a1f5a,0x4a3c10,0x4a2810,0x4a1428];

// Build meshes per region
const regionMeshes=[];
REGION_B64.forEach((b64,i)=>{
  const positions=decodeF32(b64);
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geo.computeVertexNormals();
  const mat=new THREE.MeshPhongMaterial({
    color:BASE_HEX[i], flatShading:true,
    shininess:80, specular:new THREE.Color(ACTIVE_HEX[i]).multiplyScalar(0.1),
    transparent:true, opacity:0.92
  });
  const mesh=new THREE.Mesh(geo,mat);
  brainGroup.add(mesh);
  regionMeshes.push(mesh);
});

// Wireframe overlay (full brain, faint)
const allPositions=[];
REGION_B64.forEach(b64=>{
  const f=decodeF32(b64);
  for(let i=0;i<f.length;i++) allPositions.push(f[i]);
});
const fullGeo=new THREE.BufferGeometry();
fullGeo.setAttribute('position',new THREE.Float32BufferAttribute(allPositions,3));
fullGeo.computeVertexNormals();
const wireMat=new THREE.MeshBasicMaterial({color:0xff44aa,wireframe:true,transparent:true,opacity:0.08});
const wireMesh=new THREE.Mesh(fullGeo,wireMat);
brainGroup.add(wireMesh);
const glitchMat=new THREE.MeshBasicMaterial({color:0x00ffcc,wireframe:true,transparent:true,opacity:0.04});
const glitchMesh=new THREE.Mesh(fullGeo.clone(),glitchMat);
brainGroup.add(glitchMesh);

// DOM markers
const ml=document.getElementById('markers');
let activeRegion=-1;
const markerEls=REGIONS.map((r,i)=>{
  const el=document.createElement('div');
  el.className='mk';
  el.style.cssText+=`background:${r.hex};box-shadow:0 0 14px ${r.hex}99,0 0 4px ${r.hex};`;
  el.textContent=i+1;
  el.addEventListener('click',()=>selectRegion(i));
  ml.appendChild(el);
  return el;
});

// Legend
const legend=document.getElementById('legend');
REGIONS.forEach((r,i)=>{
  const item=document.createElement('div');
  item.className='leg-item';
  item.innerHTML=`<div class="leg-dot" style="background:${r.hex}"></div><span>${r.name}</span>`;
  item.addEventListener('click',()=>selectRegion(i));
  legend.appendChild(item);
});

// Panel
const panel=document.getElementById('panel');
const panelNum=document.getElementById('panel-num');
const panelName=document.getElementById('panel-name');
const panelDesc=document.getElementById('panel-desc');
document.getElementById('panel-close').addEventListener('click',()=>deselectAll());

function selectRegion(i){
  playClick();
  activeRegion=i;
  // Color all regions: active=bright, others=dim
  regionMeshes.forEach((m,j)=>{
    if(j===i){
      m.material.color.setHex(ACTIVE_HEX[j]);
      m.material.emissive.setHex(ACTIVE_HEX[j]);
      m.material.emissiveIntensity=0.25;
      m.material.opacity=1.0;
    } else {
      m.material.color.setHex(BASE_HEX[j]);
      m.material.emissive.setHex(0x000000);
      m.material.emissiveIntensity=0;
      m.material.opacity=0.45;
    }
  });
  // Markers
  markerEls.forEach((el,j)=>{
    el.style.transform=j===i?'translate(-50%,-50%) scale(1.3)':'translate(-50%,-50%) scale(1)';
    el.style.opacity=j===i?'1':'0.4';
  });
  // Panel
  const r=REGIONS[i];
  panelNum.textContent=String(i+1).padStart(2,'0');
  panelNum.style.color=r.hex;
  panelName.textContent=r.name;
  panelName.style.color=r.hex;
  panelDesc.textContent=r.desc;
  panel.style.borderColor=r.hex+'33';
  panel.style.boxShadow=`0 0 30px ${r.hex}22`;
  panel.style.display='block';
}

function deselectAll(){
  activeRegion=-1;
  hoveredRegion=-1;
  regionMeshes.forEach((m,i)=>{
    m.material.color.setHex(BASE_HEX[i]);
    m.material.emissive.setHex(0x000000);
    m.material.emissiveIntensity=0;
    m.material.opacity=0.92;
  });
  markerEls.forEach(el=>{ el.style.opacity='1'; el.style.transform='translate(-50%,-50%) scale(1)'; });
  panel.style.display='none';
}

// Raycasting - click on mesh zones
const raycaster=new THREE.Raycaster();
const mouse=new THREE.Vector2();
let mouseDownPos={x:0,y:0};

app.addEventListener('mousedown',e=>{
  mouseDownPos={x:e.clientX,y:e.clientY};
});

app.addEventListener('click',e=>{
  // Only trigger if mouse didn't move much (not a drag)
  const dx=Math.abs(e.clientX-mouseDownPos.x);
  const dy=Math.abs(e.clientY-mouseDownPos.y);
  if(dx>5||dy>5) return;

  const rect=canvas.getBoundingClientRect();
  mouse.x=((e.clientX-rect.left)/rect.width)*2-1;
  mouse.y=-((e.clientY-rect.top)/rect.height)*2+1;
  raycaster.setFromCamera(mouse,camera);

  const hits=raycaster.intersectObjects(regionMeshes);
  if(hits.length>0){
    const idx=regionMeshes.indexOf(hits[0].object);
    if(idx>=0){
      if(activeRegion===idx) deselectAll();
      else selectRegion(idx);
    }
  }
});

// Web Audio — warm Minecraft-style orb magic sound
const AudioCtx=window.AudioContext||window.webkitAudioContext;
let audioCtx=null;
function playClick(){
  try{
    if(!audioCtx) audioCtx=new AudioCtx();
    const now=audioCtx.currentTime;

    // Reverb impulse (short room warmth)
    function makeReverb(dur=0.6,decay=3.5){
      const sr=audioCtx.sampleRate;
      const len=sr*dur;
      const buf=audioCtx.createBuffer(2,len,sr);
      for(let c=0;c<2;c++){
        const d=buf.getChannelData(c);
        for(let i=0;i<len;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/len,decay);
      }
      const conv=audioCtx.createConvolver();
      conv.buffer=buf;
      return conv;
    }
    const reverb=makeReverb(0.7,4);
    const reverbG=audioCtx.createGain(); reverbG.gain.value=0.14;
    reverb.connect(reverbG); reverbG.connect(audioCtx.destination);

    const dry=audioCtx.createGain(); dry.gain.value=0.28;
    dry.connect(audioCtx.destination);

    function note(freq, startT, dur, vol=0.5, vib=false){
      const o=audioCtx.createOscillator();
      const g=audioCtx.createGain();
      // Use triangle for warmth — no harsh harmonics
      o.type='triangle';
      o.frequency.setValueAtTime(freq,startT);
      // Slight pitch drift upward (orb-like)
      o.frequency.exponentialRampToValueAtTime(freq*1.03,startT+dur*0.6);
      // Vibrato via LFO for organic feel
      if(vib){
        const lfo=audioCtx.createOscillator();
        const lfoG=audioCtx.createGain();
        lfo.frequency.value=5.5+Math.random()*2;
        lfoG.gain.value=freq*0.012;
        lfo.connect(lfoG); lfoG.connect(o.frequency);
        lfo.start(startT); lfo.stop(startT+dur+0.1);
      }
      // Soft attack, long warm tail
      g.gain.setValueAtTime(0,startT);
      g.gain.linearRampToValueAtTime(vol,startT+0.025);
      g.gain.setValueAtTime(vol,startT+dur*0.3);
      g.gain.exponentialRampToValueAtTime(0.001,startT+dur);
      o.connect(g);
      g.connect(dry);
      g.connect(reverb);
      o.start(startT); o.stop(startT+dur+0.05);
    }

    // Minecraft orb: pentatonic cascade, staggered, warm triangle
    // Notes: C5 E5 G5 B5 E6 — bright but round
    const base=523.25;
    const penta=[1, 1.26, 1.498, 1.888, 2.52];
    const delays=[0, 0.07, 0.14, 0.22, 0.31];
    const durs  =[0.55,0.52,0.50,0.48,0.55];
    const vols  =[0.18,0.16,0.15,0.13,0.11];
    penta.forEach((ratio,i)=>{
      note(base*ratio, now+delays[i], durs[i], vols[i], true);
    });

    // Warm sub-tone underneath (gives body, not robotic)
    const sub=audioCtx.createOscillator();
    const subG=audioCtx.createGain();
    sub.type='sine';
    sub.frequency.setValueAtTime(130,now);
    sub.frequency.exponentialRampToValueAtTime(196,now+0.4);
    subG.gain.setValueAtTime(0,now);
    subG.gain.linearRampToValueAtTime(0.07,now+0.03);
    subG.gain.exponentialRampToValueAtTime(0.001,now+0.55);
    sub.connect(subG); subG.connect(dry);
    sub.start(now); sub.stop(now+0.6);

    // Soft high shimmer (like sparks, very quiet)
    [0.02,0.09,0.17,0.26,0.34].forEach((d,i)=>{
      const s=audioCtx.createOscillator();
      const sg=audioCtx.createGain();
      s.type='sine';
      const f=2093+i*420+Math.random()*200;
      s.frequency.setValueAtTime(f,now+d);
      s.frequency.exponentialRampToValueAtTime(f*1.08,now+d+0.12);
      sg.gain.setValueAtTime(0,now+d);
      sg.gain.linearRampToValueAtTime(0.03,now+d+0.01);
      sg.gain.exponentialRampToValueAtTime(0.001,now+d+0.18);
      s.connect(sg); sg.connect(reverb);
      s.start(now+d); s.stop(now+d+0.2);
    });

  }catch(e){}
}

// Rotation controls
let drag=false,px=0,py=0,rotX=0.1,rotY=0;
app.addEventListener('mousemove',e=>{
  if(drag) return;
  const rect=canvas.getBoundingClientRect();
  mouse.x=((e.clientX-rect.left)/rect.width)*2-1;
  mouse.y=-((e.clientY-rect.top)/rect.height)*2+1;
  raycaster.setFromCamera(mouse,camera);
  const hits=raycaster.intersectObjects(regionMeshes);
  const newHover=hits.length>0?regionMeshes.indexOf(hits[0].object):-1;
  if(newHover!==hoveredRegion){
    // restore old hovered (if not active)
    if(hoveredRegion>=0&&hoveredRegion!==activeRegion){
      regionMeshes[hoveredRegion].material.color.setHex(activeRegion>=0?BASE_HEX[hoveredRegion]:BASE_HEX[hoveredRegion]);
      regionMeshes[hoveredRegion].material.emissive.setHex(0x000000);
      regionMeshes[hoveredRegion].material.emissiveIntensity=0;
    }
    hoveredRegion=newHover;
    // highlight new hovered (if not active)
    if(hoveredRegion>=0&&hoveredRegion!==activeRegion){
      regionMeshes[hoveredRegion].material.color.setHex(HOVER_HEX[hoveredRegion]);
      regionMeshes[hoveredRegion].material.emissive.setHex(ACTIVE_HEX[hoveredRegion]);
      regionMeshes[hoveredRegion].material.emissiveIntensity=0.18;
    }
  }
  canvas.style.cursor=newHover>=0?'pointer':'grab';
});

app.addEventListener('mousedown',e=>{drag=true;px=e.clientX;py=e.clientY;canvas.style.cursor='grabbing';});
window.addEventListener('mouseup',()=>{drag=false;canvas.style.cursor='grab';});
window.addEventListener('mousemove',e=>{
  if(!drag)return;
  rotY+=(e.clientX-px)*0.009; rotX+=(e.clientY-py)*0.009;
  rotX=Math.max(-1.4,Math.min(1.4,rotX));
  px=e.clientX; py=e.clientY;
});
app.addEventListener('wheel',e=>{
  e.preventDefault();
  camera.position.z=Math.max(1.8,Math.min(7,camera.position.z+e.deltaY*0.005));
},{passive:false});

// ── Touch events ──────────────────────────────────────────────────────────
let touchStartPos={x:0,y:0};
let pinchStartDist=0;

function getTouchDist(t){
  const dx=t[0].clientX-t[1].clientX;
  const dy=t[0].clientY-t[1].clientY;
  return Math.sqrt(dx*dx+dy*dy);
}

app.addEventListener('touchstart',e=>{
  e.preventDefault();
  if(e.touches.length===1){
    drag=true;
    px=e.touches[0].clientX;
    py=e.touches[0].clientY;
    touchStartPos={x:px,y:py};
  } else if(e.touches.length===2){
    drag=false;
    pinchStartDist=getTouchDist(e.touches);
  }
},{passive:false});

app.addEventListener('touchmove',e=>{
  e.preventDefault();
  if(e.touches.length===1 && drag){
    const cx=e.touches[0].clientX;
    const cy=e.touches[0].clientY;
    rotY+=(cx-px)*0.009; rotX+=(cy-py)*0.009;
    rotX=Math.max(-1.4,Math.min(1.4,rotX));
    px=cx; py=cy;
  } else if(e.touches.length===2){
    const dist=getTouchDist(e.touches);
    const delta=pinchStartDist-dist;
    camera.position.z=Math.max(1.8,Math.min(7,camera.position.z+delta*0.012));
    pinchStartDist=dist;
  }
},{passive:false});

app.addEventListener('touchend',e=>{
  e.preventDefault();
  if(e.touches.length===0){
    // tap detection: if barely moved, treat as a click/select
    const dx=Math.abs((e.changedTouches[0]?.clientX||px)-touchStartPos.x);
    const dy=Math.abs((e.changedTouches[0]?.clientY||py)-touchStartPos.y);
    if(drag && dx<8 && dy<8){
      // Fire raycaster at tap position
      const rect=canvas.getBoundingClientRect();
      const tx=e.changedTouches[0].clientX;
      const ty=e.changedTouches[0].clientY;
      mouse.x=((tx-rect.left)/rect.width)*2-1;
      mouse.y=-((ty-rect.top)/rect.height)*2+1;
      raycaster.setFromCamera(mouse,camera);
      const hits=raycaster.intersectObjects(regionMeshes);
      if(hits.length>0){
        const idx=regionMeshes.indexOf(hits[0].object);
        if(idx>=0){
          if(activeRegion===idx) deselectAll();
          else selectRegion(idx);
        }
      }
    }
    drag=false;
  }
},{passive:false});

// Update marker DOM positions
function updateMarkers(){
  MARKERS.forEach((pos,i)=>{
    const v=new THREE.Vector3(...pos).applyEuler(brainGroup.rotation);
    v.project(camera);
    const x=(v.x+1)/2*W, y=(-v.y+1)/2*H;
    const el=markerEls[i];
    const vis=v.z<1;
    el.style.display=vis?'flex':'none';
    if(vis){ el.style.left=x+'px'; el.style.top=y+'px'; el.style.opacity=activeRegion>=0?(i===activeRegion?'1':'0.35'):(Math.max(0,1-Math.max(0,v.z)*3)).toFixed(2); }
  });
}

let t=0,glitchOn=false;
function animate(){
  requestAnimationFrame(animate);
  t+=0.016;
  brainGroup.rotation.y=rotY+t*0.004;
  brainGroup.rotation.x=rotX;
  pt.position.x=Math.sin(t*0.5)*2;
  pt.position.z=Math.cos(t*0.4)*1.5+1.5;
  if(!glitchOn&&Math.random()<0.007){
    glitchOn=true;
    glitchMat.opacity=0.2+Math.random()*0.18;
    wireMat.opacity=0.3+Math.random()*0.25;
    glitchMesh.position.x=(Math.random()-0.5)*0.04;
    glitchMesh.position.y=(Math.random()-0.5)*0.03;
    setTimeout(()=>{glitchOn=false;glitchMat.opacity=0.04;wireMat.opacity=0.08;glitchMesh.position.set(0,0,0);},60+Math.random()*100);
  }
  renderer.render(scene,camera);
  updateMarkers();
}
animate();

window.addEventListener('resize',()=>{
  W=app.clientWidth; H=app.clientHeight;
  renderer.setSize(W,H); camera.aspect=W/H; camera.updateProjectionMatrix();
});
</script>
