<script>
  // Respuestas correctas: A=1, B=2, C=3, D=4, E=5, F=6
  var correctas = { A: '1', B: '2', C: '3', D: '4', E: '5', F: '6' };

  var mensajesOk = {
    A: 'Correcto: el lóbulo frontal controla la toma de decisiones, las emociones, la personalidad y el autocontrol.',
    B: 'Correcto: el lóbulo parietal procesa el tacto, la temperatura y la orientación espacial.',
    C: 'Correcto: el lóbulo temporal procesa el lenguaje, la memoria auditiva y el reconocimiento de objetos.',
    D: 'Correcto: el lóbulo occipital interpreta colores, formas y movimiento visual.',
    E: 'Correcto: el cerebelo coordina el movimiento, el equilibrio y la precisión motora.',
    F: 'Correcto: el tronco encefálico regula la respiración, el ritmo cardíaco y los ciclos de sueño.'
  };

  var mensajesFail = {
    A: 'Incorrecto. El lóbulo frontal controla la toma de decisiones, las emociones, la personalidad y el autocontrol.',
    B: 'Incorrecto. El lóbulo parietal procesa el tacto, la temperatura y la orientación espacial.',
    C: 'Incorrecto. El lóbulo temporal procesa el lenguaje, la memoria auditiva y el reconocimiento de objetos.',
    D: 'Incorrecto. El lóbulo occipital interpreta colores, formas y movimiento visual.',
    E: 'Incorrecto. El cerebelo coordina el movimiento, el equilibrio y la precisión motora.',
    F: 'Incorrecto. El tronco encefálico regula la respiración, el ritmo cardíaco y los ciclos de sueño.'
  };

  function clearFeedback(letra) {
    var fb = document.getElementById('fb-' + letra);
    fb.textContent = '';
    fb.className = 'item-feedback';
    document.getElementById('sel-' + letra).classList.remove('correct', 'wrong');
    document.getElementById('resultado').classList.remove('show');
  }

  function verificar() {
    var letras = ['A', 'B', 'C', 'D', 'E', 'F'];
    var aciertos = 0;
    var sinResponder = false;

    letras.forEach(function (l) {
      var sel = document.getElementById('sel-' + l);
      var fb = document.getElementById('fb-' + l);
      var val = sel.value;

      if (!val) {
        sinResponder = true;
        fb.textContent = '⚠ selecciona una opción';
        fb.className = 'item-feedback fail show';
        sel.classList.remove('correct', 'wrong');
        return;
      }

      sel.classList.remove('correct', 'wrong');
      fb.className = 'item-feedback show';

      if (val === correctas[l]) {
        aciertos++;
        sel.classList.add('correct');
        fb.classList.add('ok');
        fb.textContent = '✓ ' + mensajesOk[l];
      } else {
        sel.classList.add('wrong');
        fb.classList.add('fail');
        fb.textContent = '✗ ' + mensajesFail[l];
      }
    });

    if (sinResponder) return;

    var res = document.getElementById('resultado');
    var scoreEl = document.getElementById('score-text');
    var msgEl = document.getElementById('score-msg');

    scoreEl.textContent = aciertos + ' / 6 correctas';
    res.classList.remove('perfect', 'partial', 'fail');
    res.classList.add('show');

    if (aciertos === 6) {
      res.classList.add('perfect');
      msgEl.textContent = '¡Perfecto! Dominas las estructuras del cerebro. Tu sistema neuronal está en modo élite.';
    } else if (aciertos >= 4) {
      res.classList.add('partial');
      msgEl.textContent = 'Bien hecho. Revisa las respuestas incorrectas y consolida el conocimiento que te falta.';
    } else {
      res.classList.add('fail');
      msgEl.textContent = 'Sigue intentándolo. Repasa las tarjetas de referencia y vuelve a verificar tus respuestas.';
    }
  }

  function reiniciar() {
    var letras = ['A', 'B', 'C', 'D', 'E', 'F'];
    letras.forEach(function (l) {
      var sel = document.getElementById('sel-' + l);
      sel.value = '';
      sel.classList.remove('correct', 'wrong');
      var fb = document.getElementById('fb-' + l);
      fb.textContent = '';
      fb.className = 'item-feedback';
    });
    var res = document.getElementById('resultado');
    res.classList.remove('show', 'perfect', 'partial', 'fail');
  }
</script>
