  book:  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>`,
  moon:  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a6.364 6.364 0 0 0 9 9 9 9 0 1 1-9-9z"/></svg>`,
  heart: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`,
  target:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg>`,
};

const MCQ = [
  {q:"¿Cuál de los siguientes neurotransmisores se libera principalmente cuando sentimos alegría durante el aprendizaje?",opts:["Cortisol y adrenalina","Dopamina y serotonina","Norepinefrina y acetilcolina","Melatonina y histamina"],ans:1,fb:"La alegría activa la liberación de dopamina y serotonina, que estimulan los circuitos de recompensa y facilitan la fijación de recuerdos en el hipocampo."},
  {q:"¿Qué efecto tiene la curiosidad sobre el aprendizaje según la neurociencia?",opts:["Disminuye la actividad del hipocampo","Bloquea la corteza prefrontal","Activa el sistema de recompensa y prepara el cerebro para aprender","Genera la misma respuesta que el miedo"],ans:2,fb:"La curiosidad pone al cerebro en 'modo exploración', liberando dopamina por anticipado y aumentando la actividad del hipocampo y la corteza prefrontal."},
  {q:"Un estudiante con estrés crónico tiene dificultades para recordar lo que estudió. ¿Cuál es la razón principal?",opts:["El estrés crónico aumenta la motivación en exceso","El cortisol en niveles altos puede dañar el hipocampo","La adrenalina mejora demasiado la memoria","El estrés no tiene relación con la memoria"],ans:1,fb:"El estrés crónico eleva los niveles de cortisol, que en exceso interfiere con el hipocampo, dificultando tanto la consolidación como la recuperación de recuerdos."},
  {q:"Dormir después de estudiar es beneficioso principalmente porque...",opts:["El cerebro deja de usar energía y descansa","El hipocampo transfiere los recuerdos a la corteza para almacenamiento a largo plazo","El sueño borra los recuerdos negativos del día","La temperatura corporal baja mejora la concentración"],ans:1,fb:"Durante el sueño profundo, el hipocampo 'reproduce' los aprendizajes del día y los transfiere a la corteza cerebral. Este proceso se llama consolidación dependiente del sueño."},
  {q:"¿Cuántas horas de sueño necesitan los adolescentes para un óptimo rendimiento académico?",opts:["4 a 6 horas","6 a 7 horas","8 a 10 horas","Más de 12 horas"],ans:2,fb:"Los adolescentes necesitan entre 8 y 10 horas porque sus cerebros están en un período crítico de desarrollo y consolidación de aprendizajes."},
  {q:"¿Por qué usar el celular mientras se estudia afecta negativamente el aprendizaje?",opts:["La luz de la pantalla daña la vista","Cada notificación interrumpe el estado cognitivo y recuperar la concentración toma ~23 minutos","El celular reduce los niveles de dopamina","El sonido de notificaciones activa el sueño profundo"],ans:1,fb:"Cada interrupción rompe el estado de 'flujo' cognitivo. Recuperar la concentración plena toma aproximadamente 23 minutos, reduciendo la efectividad total del estudio."},
  {q:"¿Qué sucede en el cerebro cuando sentimos miedo intenso durante el aprendizaje?",opts:["La amígdala se desactiva para priorizar el aprendizaje","La amígdala se activa y reduce la función de la corteza prefrontal","El hipocampo trabaja más rápido para memorizar","El sueño REM aumenta compensando el impacto"],ans:1,fb:"El miedo activa la amígdala (respuesta de supervivencia), que inhibe la corteza prefrontal, responsable del pensamiento racional. Por eso el miedo 'bloquea' la mente."},
  {q:"La técnica Pomodoro (25 min de estudio + 5 min de descanso) es efectiva porque...",opts:["Permite estudiar más horas sin dormir","Respeta los ciclos naturales de atención sostenida del cerebro","Activa la amígdala para mejorar la concentración","Reduce los niveles de serotonina"],ans:1,fb:"La atención sostenida tiene límites biológicos. Los descansos programados reinician el ciclo de atención, reducen la fatiga cognitiva y mejoran la calidad total del estudio."},
];

const TF = [
  {stmt:"Dormir pocas horas la noche antes de un examen puede mejorar la memoria porque el cerebro permanece más activo.",ans:false,fb:"La privación de sueño impide la consolidación de recuerdos. Lo que se estudió sin dormir bien difícilmente se recordará con claridad durante el examen."},
  {stmt:"La curiosidad activa el sistema de recompensa del cerebro incluso antes de que ocurra el aprendizaje.",ans:true,fb:"La curiosidad pone al cerebro en 'modo anticipación de recompensa', liberando dopamina por anticipado. Esto prepara y motiva al cerebro para absorber nueva información."},
  {stmt:"El estrés excesivo durante una evaluación puede hacer que el estudiante olvide contenidos que sabía perfectamente.",ans:true,fb:"El estrés agudo eleva el cortisol, que interfiere con la recuperación de recuerdos. Este fenómeno se conoce como 'bloqueo por ansiedad'."},
  {stmt:"Releer los apuntes varias veces es la técnica de estudio más efectiva para recordar a largo plazo.",ans:false,fb:"Releer produce reconocimiento pero no garantiza recuperación real. Técnicas como autoevaluarse o explicar los conceptos son 2-3 veces más efectivas."},
  {stmt:"Un ambiente de aprendizaje seguro, donde el error es bienvenido, mejora el rendimiento académico.",ans:true,fb:"Los entornos seguros reducen la activación de la amígdala, permitiendo que la corteza prefrontal trabaje de forma óptima y se establezcan conexiones cognitivas más profundas."},
  {stmt:"El cerebro humano puede mantener la atención plena de forma indefinida sin necesitar descansos.",ans:false,fb:"La atención sostenida tiene límites biológicos. Después de 20-30 minutos sin descanso, la concentración disminuye notablemente. Los descansos son parte esencial del aprendizaje."},
  {stmt:"Las emociones positivas como la alegría y la curiosidad amplían nuestra capacidad cognitiva y mejoran la creatividad.",ans:true,fb:"La teoría de 'ampliar y construir' muestra que las emociones positivas expanden el pensamiento, la atención y la capacidad de establecer conexiones creativas entre conceptos."},
];

const CASE = {
  scenario:"Juan tiene un examen de ciencias mañana. Decide estudiar hasta las 2 de la madrugada, con la televisión de fondo y revisando su teléfono cada pocos minutos. No desayunó bien, y está muy nervioso porque siente que 'si falla el examen, todo estará perdido'. Cuando llega al examen, su mente se siente 'en blanco'.",
  items:[
    {text:"Estudia hasta las 2 AM (trasnocha)",type:"bad"},
    {text:"Usa la televisión como fondo de estudio",type:"bad"},
    {text:"Revisa el teléfono frecuentemente",type:"bad"},
    {text:"No desayunó bien antes del examen",type:"bad"},
    {text:"Piensa que 'todo estará perdido' si falla",type:"bad"},
  ],
  correctBads:[0,1,2,3,4],
};

let stage=0,score=0,mcqIdx=0,tfIdx=0,caseSelected=[],caseChecked=false;

function upd(){
  const pcts=[0,25,50,75];
  document.getElementById('progressFill').style.width=pcts[stage]+'%';
  document.getElementById('progressLabel').textContent=`ETAPA ${stage+1} DE 4`;
  document.getElementById('scoreLabel').textContent=`PUNTAJE: ${score}`;
  for(let i=0;i<4;i++){const d=document.getElementById('dot'+i);d.className='stage-dot'+(i<stage?' done':i===stage?' active':'');}
}

function renderMCQ(){
  if(mcqIdx>=MCQ.length){stage=1;upd();renderTF();return;}
  const q=MCQ[mcqIdx]; const letters=['A','B','C','D'];
  document.getElementById('contentArea').innerHTML=`
    <div class="stage-header">
      <div class="stage-label">${ICO.target} ETAPA 1 — SELECCIÓN MÚLTIPLE</div>
      <div class="stage-title">Pregunta ${mcqIdx+1} de ${MCQ.length}</div>
    </div>
    <div class="question-card">
      <div class="question-number">${ICO.check} PREGUNTA ${mcqIdx+1}</div>
      <div class="question-text">${q.q}</div>
      <div class="options-list">
        ${q.opts.map((o,i)=>`<button class="option-btn" onclick="answerMCQ(${i})" id="opt${i}"><span class="opt-letter">${letters[i]}</span>${o}</button>`).join('')}
      </div>
      <div class="feedback-block" id="mcqFb"></div>
      <button class="next-btn" id="mcqNext" onclick="mcqIdx++;renderMCQ()">${ICO.arrow} ${mcqIdx+1<MCQ.length?'Siguiente pregunta':'Ir a Etapa 2'}</button>
    </div>`;
}
function answerMCQ(chosen){
  if(document.getElementById('opt0').disabled) return;
  const q=MCQ[mcqIdx];
  document.querySelectorAll('.option-btn').forEach(b=>b.disabled=true);
  const fb=document.getElementById('mcqFb');
  if(chosen===q.ans){document.getElementById('opt'+chosen).classList.add('correct');fb.innerHTML=ICO.check+' '+q.fb;fb.className='feedback-block ok show';score++;}
  else{document.getElementById('opt'+chosen).classList.add('wrong');document.getElementById('opt'+q.ans).classList.add('correct');fb.innerHTML=ICO.x+' Incorrecto. '+q.fb;fb.className='feedback-block ko show';}
  document.getElementById('scoreLabel').textContent='PUNTAJE: '+score;
  document.getElementById('mcqNext').classList.add('show');
}

function renderTF(){
  if(tfIdx>=TF.length){stage=2;upd();renderCase();return;}
  const q=TF[tfIdx];
  document.getElementById('contentArea').innerHTML=`
    <div class="stage-header">
      <div class="stage-label">${ICO.check} ETAPA 2 — VERDADERO O FALSO</div>
      <div class="stage-title">Afirmación ${tfIdx+1} de ${TF.length}</div>
    </div>
    <div class="question-card">
      <div class="question-number">${ICO.check} AFIRMACIÓN ${tfIdx+1}</div>
      <div class="question-text">"${q.stmt}"</div>
      <div class="tf-options">
        <button class="tf-btn" onclick="answerTF(true)" id="tfTrue">${ICO.check} VERDADERO</button>
        <button class="tf-btn" onclick="answerTF(false)" id="tfFalse">${ICO.x} FALSO</button>
      </div>
      <div class="feedback-block" id="tfFb"></div>
      <button class="next-btn" id="tfNext" onclick="tfIdx++;renderTF()">${ICO.arrow} ${tfIdx+1<TF.length?'Siguiente afirmación':'Ir a Etapa 3'}</button>
    </div>`;
}
function answerTF(chosen){
  if(document.getElementById('tfTrue').disabled) return;
  const q=TF[tfIdx];
  document.querySelectorAll('.tf-btn').forEach(b=>b.disabled=true);
  const fb=document.getElementById('tfFb');
  const isOk=(chosen===q.ans);
  if(isOk){document.getElementById(chosen?'tfTrue':'tfFalse').classList.add('correct');fb.innerHTML=ICO.check+' '+q.fb;fb.className='feedback-block ok show';score++;}
  else{document.getElementById(chosen?'tfTrue':'tfFalse').classList.add('wrong');document.getElementById(q.ans?'tfTrue':'tfFalse').classList.add('correct');fb.innerHTML=ICO.x+' Incorrecto. '+q.fb;fb.className='feedback-block ko show';}
  document.getElementById('scoreLabel').textContent='PUNTAJE: '+score;
  document.getElementById('tfNext').classList.add('show');
}

function renderCase(){
  caseSelected=[];caseChecked=false;
  const itemsHtml=CASE.items.map((item,i)=>`
    <div class="case-item" id="citem${i}" onclick="toggleCase(${i})">
      <div class="case-checkbox" id="cbox${i}">${ICO.check}</div>
      <div>${item.text}</div>
    </div>`).join('');
  document.getElementById('contentArea').innerHTML=`
    <div class="stage-header">
      <div class="stage-label">${ICO.book} ETAPA 3 — CASO PRÁCTICO</div>
      <div class="stage-title">Analiza la situación</div>
    </div>
    <div class="case-card">
      <div class="case-scenario">${CASE.scenario}</div>
      <div class="case-question">${ICO.x} Identifica TODOS los hábitos inadecuados de Juan:</div>
      <div class="case-checklist">${itemsHtml}</div>
      <div class="feedback-block" id="caseFb"></div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:1rem">
        <button class="next-btn show" id="caseCheck" onclick="checkCase()" style="background:var(--ne-teal);color:#000">${ICO.check} Verificar análisis</button>
        <button class="next-btn" id="caseNext" onclick="stage=3;renderResults()">${ICO.arrow} Ver resultados finales</button>
      </div>
    </div>`;
}
function toggleCase(i){
  if(caseChecked) return;
  const idx=caseSelected.indexOf(i);const item=document.getElementById('citem'+i);
  if(idx===-1){caseSelected.push(i);item.classList.add('selected-bad');}
  else{caseSelected.splice(idx,1);item.classList.remove('selected-bad');}
}
function checkCase(){
  if(caseChecked) return; caseChecked=true;
  const correct=caseSelected.filter(i=>CASE.correctBads.includes(i)).length;
  const fp=caseSelected.filter(i=>!CASE.correctBads.includes(i)).length;
  const missed=CASE.correctBads.filter(i=>!caseSelected.includes(i)).length;
  score+=Math.max(0,correct-fp);
  CASE.items.forEach((_,i)=>{
    const el=document.getElementById('citem'+i);
    const isSelected=caseSelected.includes(i);
    const shouldBe=CASE.correctBads.includes(i);
    if(isSelected&&shouldBe) el.style.borderColor='var(--ne-green)';
    else if(isSelected&&!shouldBe){el.style.borderColor='var(--ne-pink)';el.style.background='rgba(255,92,122,0.1)';}
    else if(!isSelected&&shouldBe){el.style.borderColor='var(--ne-yellow)';el.style.background='rgba(255,204,0,0.05)';}
  });
  const fb=document.getElementById('caseFb');
  let msg=`<strong>Identificados correctamente: ${correct}/${CASE.correctBads.length}</strong>`;
  if(missed>0) msg+=`<br>Te faltó identificar ${missed} hábito(s) inadecuado(s) (marcados en amarillo).`;
  if(fp>0) msg+=`<br>Marcaste ${fp} elemento(s) que no corresponden a malos hábitos.`;
  msg+=`<br>En el caso de Juan, prácticamente todos sus hábitos son inadecuados.`;
  fb.innerHTML=msg; fb.className=`feedback-block ${correct>=3?'ok':'ko'} show`;
  document.getElementById('scoreLabel').textContent='PUNTAJE: '+score;
  document.getElementById('caseCheck').style.display='none';
  document.getElementById('caseNext').classList.add('show');
}

function renderResults(){
  document.getElementById('progressFill').style.width='100%';
  document.getElementById('progressLabel').textContent='MISIÓN COMPLETADA';
  for(let i=0;i<4;i++) document.getElementById('dot'+i).className='stage-dot done';
  const maxP=MCQ.length+TF.length+CASE.correctBads.length;
  const pct=Math.round(score/maxP*100);
  let medal,level,color,msg;
  if(pct>=85){medal=ICO.trophy;level='Maestro de las Emociones';color='var(--ne-yellow)';msg='¡Extraordinario! Demostraste un dominio completo de cómo las emociones, el sueño y los hábitos impactan el aprendizaje. Tu cerebro está listo para el siguiente nivel.';}
  else if(pct>=65){medal=ICO.star;level='Explorador Mental';color='var(--ne-teal)';msg='¡Muy bien! Tienes una sólida comprensión de los temas de la Misión 3. Repasa los puntos donde tuviste dificultad y estarás listo para dominarlos completamente.';}
  else{medal=ICO.heart;level='Aprendiz Cerebral';color='var(--ne-pink)';msg='Buen intento. El aprendizaje es un proceso y cada error es una oportunidad. Revisa los contenidos de emociones, sueño y hábitos de estudio antes de continuar.';}
  document.getElementById('contentArea').innerHTML=`
    <div class="results-screen">
      <div class="results-medal" style="color:${color}">${medal}</div>
      <div class="results-level" style="color:${color}">${level}</div>
      <div class="results-score">${score} / ${maxP}</div>
      <div class="results-pct">${pct}% de dominio</div>
      <div class="results-msg">${msg}</div>
      <div class="results-skills">
        <div class="results-skill">${ICO.heart} Emociones y Aprendizaje</div>
        <div class="results-skill">${ICO.moon} Sueño y Descanso</div>
        <div class="results-skill">${ICO.book} Hábitos de Estudio</div>
        <div class="results-skill">${ICO.target} Análisis de Casos</div>
      </div>
      <button class="restart-btn" onclick="restartAll()">${ICO.refresh} Intentar de nuevo</button>
    </div>`;
  document.getElementById('statusLabel').textContent='NIVEL: '+level.toUpperCase();
  document.getElementById('scoreLabel').textContent=pct+'% COMPLETADO';
}

function restartAll(){score=0;mcqIdx=0;tfIdx=0;caseSelected=[];caseChecked=false;stage=0;upd();renderMCQ();}

upd(); renderMCQ();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1780280922747-mvo6mgsj0","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<p></p>
<style>
:root {
  --dark:   #04060e;
  --dark2:  #080a14;
  --panel:  #0c0e1c;
  --border: #161929;
  --pink:   #ff4d6d;
  --teal:   #00e5ff;
  --green:  #00ff9d;
  --yellow: #ffd60a;
  --purple: #b24bff;
  --text:   #b8c0d4;
  --bright: #e8ecf5;
  --fp: 'Press Start 2P', monospace;
  --fo: 'Orbitron', monospace;
  --fm: 'Share Tech Mono', monospace;
}
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;}
body{
  background:var(--dark);
  font-family:var(--fm);
  color:var(--text);
  min-height:100vh;
  overflow-x:hidden;
}

/* ── SCANLINE OVERLAY ── */
body::before{
  content:'';position:fixed;inset:0;pointer-events:none;z-index:9999;
  background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.06) 3px,rgba(0,0,0,0.06) 4px);
  opacity:0.4;
}

/* ── ANIMATED GRID BG ── */
#grid-bg{
  position:fixed;inset:0;z-index:0;overflow:hidden;
}
#grid-bg canvas{width:100%;height:100%;}

/* ── TOPBAR ── */
#topbar{
  position:sticky;top:0;z-index:500;
  background:rgba(4,6,14,0.92);
  backdrop-filter:blur(12px);
  border-bottom:1px solid rgba(255,77,109,0.3);
  display:flex;align-items:center;
  padding:0 clamp(14px,3vw,32px);
  height:52px;gap:16px;
}
.tb-dot{width:8px;height:8px;background:var(--pink);border-radius:50%;flex-shrink:0;animation:blink 1.4s step-end infinite;box-shadow:0 0 8px var(--pink);}
.tb-title{font-family:var(--fo);color:var(--pink);font-size:clamp(0.45rem,1.3vw,0.72rem);letter-spacing:4px;text-transform:uppercase;flex:1;font-weight:700;}
#sys-time{font-family:var(--fm);color:var(--teal);font-size:clamp(0.5rem,1vw,0.72rem);letter-spacing:2px;opacity:0.8;}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}

/* ── PAGE ── */
#page{position:relative;z-index:10;max-width:900px;margin:0 auto;padding:clamp(20px,4vw,48px) clamp(14px,3vw,28px) 80px;}

/* ── HERO ── */
#hero{text-align:center;padding:clamp(32px,6vh,72px) 0 clamp(24px,4vh,48px);position:relative;}

/* floating orbs */
.orb{
  position:absolute;border-radius:50%;filter:blur(60px);pointer-events:none;
  animation:orbFloat 6s ease-in-out infinite;
}
.orb-1{width:300px;height:300px;background:rgba(255,77,109,0.12);top:-80px;left:-100px;animation-delay:0s;}
.orb-2{width:250px;height:250px;background:rgba(0,229,255,0.1);top:-60px;right:-80px;animation-delay:2s;}
.orb-3{width:200px;height:200px;background:rgba(178,75,255,0.1);bottom:-40px;left:50%;transform:translateX(-50%);animation-delay:4s;}
@keyframes orbFloat{0%,100%{transform:translateY(0) scale(1);}50%{transform:translateY(-20px) scale(1.05);}}

/* badge */
.hero-badge{
  display:inline-flex;align-items:center;gap:10px;
  background:rgba(255,77,109,0.08);
  border:1px solid rgba(255,77,109,0.4);
  border-radius:30px;padding:8px 20px;
  font-family:var(--fm);font-size:clamp(0.48rem,0.9vw,0.62rem);
  color:var(--pink);letter-spacing:3px;text-transform:uppercase;
  margin-bottom:28px;
  animation:fadeSlideDown 0.6s ease both;
  box-shadow:0 0 20px rgba(255,77,109,0.15);
}
.badge-dot{width:6px;height:6px;background:var(--pink);border-radius:50%;animation:blink 1s step-end infinite;box-shadow:0 0 6px var(--pink);}

/* main title */
.hero-title-wrap{margin-bottom:16px;animation:fadeSlideDown 0.7s ease 0.1s both;}
.hero-title-line1{
  font-family:var(--fo);
  font-size:clamp(1.4rem,6vw,4.5rem);
  font-weight:900;
  letter-spacing:clamp(4px,1vw,12px);
  text-transform:uppercase;
  line-height:1.1;
  background:linear-gradient(135deg,var(--pink) 0%,#ff8fa3 40%,var(--purple) 70%,var(--teal) 100%);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  animation:glitch 10s steps(1) infinite, shimmer 4s linear infinite;
  background-size:200% auto;
  display:block;
}
.hero-title-line2{
  font-family:var(--fo);
  font-size:clamp(0.65rem,2.8vw,1.8rem);
  font-weight:700;
  letter-spacing:clamp(3px,0.8vw,10px);
  color:var(--teal);
  text-transform:uppercase;
  display:block;
  margin-top:8px;
  text-shadow:0 0 20px rgba(0,229,255,0.5);
  animation:fadeSlideUp 0.8s ease 0.2s both;
}
@keyframes glitch{
  0%,85%,100%{filter:none;}
  87%{filter:drop-shadow(3px 0 0 rgba(0,229,255,0.7)) drop-shadow(-3px 0 0 rgba(255,77,109,0.7));}
  89%{filter:drop-shadow(-3px 0 0 rgba(0,229,255,0.7)) drop-shadow(3px 0 0 rgba(255,77,109,0.7));}
  91%{filter:none;}
}
@keyframes shimmer{
  0%{background-position:0% center;}
  100%{background-position:200% center;}
}

/* separator line */
.hero-sep{
  display:flex;align-items:center;gap:14px;
  margin:clamp(20px,3vh,32px) auto;
  max-width:500px;
  animation:fadeIn 1s ease 0.4s both;
}
.sep-line{flex:1;height:1px;background:linear-gradient(90deg,transparent,rgba(0,229,255,0.4),transparent);}
.sep-diamond{
  width:10px;height:10px;background:var(--teal);
  transform:rotate(45deg);
  box-shadow:0 0 10px var(--teal);
  animation:pulse 2s ease-in-out infinite;
}
@keyframes pulse{0%,100%{transform:rotate(45deg) scale(1);}50%{transform:rotate(45deg) scale(1.3);}}

/* ── INTRO CONTENT ── */
#intro{
  position:relative;
  background:rgba(12,14,28,0.7);
  border:1px solid rgba(0,229,255,0.15);
  border-radius:16px;
  padding:clamp(24px,4vw,48px);
  overflow:hidden;
  backdrop-filter:blur(8px);
  animation:fadeSlideUp 0.8s ease 0.3s both;
}
#intro::before{
  content:'';position:absolute;top:0;left:0;right:0;height:2px;
  background:linear-gradient(90deg,transparent,var(--pink),var(--teal),var(--purple),transparent);
  animation:scanH 3s linear infinite;
}
#intro::after{
  content:'';position:absolute;bottom:0;left:0;right:0;height:1px;
  background:linear-gradient(90deg,transparent,rgba(0,229,255,0.3),transparent);
}
@keyframes scanH{0%{background-position:-100% 0;}100%{background-position:200% 0;}}

/* corner brackets */
.corner{position:absolute;width:20px;height:20px;}
.corner-tl{top:-1px;left:-1px;border-top:2px solid var(--pink);border-left:2px solid var(--pink);border-radius:16px 0 0 0;}
.corner-tr{top:-1px;right:-1px;border-top:2px solid var(--teal);border-right:2px solid var(--teal);border-radius:0 16px 0 0;}
.corner-bl{bottom:-1px;left:-1px;border-bottom:2px solid var(--teal);border-left:2px solid var(--teal);border-radius:0 0 0 16px;}
.corner-br{bottom:-1px;right:-1px;border-bottom:2px solid var(--pink);border-right:2px solid var(--pink);border-radius:0 0 16px 0;}

/* intro paragraphs */
.intro-paragraphs{
  display:flex;flex-direction:column;
  gap:clamp(16px,2.5vh,24px);
  margin-bottom:clamp(24px,4vh,40px);
}
.intro-p{
  font-family:var(--fm);
  font-size:clamp(0.75rem,1.4vw,1rem);
  line-height:1.9;
  color:var(--text);
  opacity:0;
  transform:translateY(14px);
  transition:opacity 0.5s ease, transform 0.5s ease;
}
.intro-p.visible{opacity:1;transform:none;}
.intro-p .hl-pink{color:var(--pink);font-weight:700;text-shadow:0 0 10px rgba(255,77,109,0.4);}
.intro-p .hl-teal{color:var(--teal);text-shadow:0 0 8px rgba(0,229,255,0.3);}
.intro-p .hl-green{color:var(--green);text-shadow:0 0 8px rgba(0,255,157,0.3);}
.intro-p .hl-yellow{color:var(--yellow);}

/* topic chips */
.topic-chips{
  display:flex;flex-wrap:wrap;gap:10px;
  margin:clamp(12px,2vh,20px) 0 clamp(20px,3vh,32px);
}
.chip{
  display:inline-flex;align-items:center;gap:8px;
  background:rgba(255,255,255,0.04);
  border:1px solid rgba(255,255,255,0.1);
  border-radius:30px;
  padding:7px 16px;
  font-family:var(--fm);font-size:clamp(0.52rem,0.9vw,0.68rem);
  color:var(--text);letter-spacing:1px;
  transition:all 0.25s;cursor:default;
  opacity:0;transform:scale(0.9);
  animation:chipIn 0.4s ease forwards;
}
.chip:hover{background:rgba(255,255,255,0.08);border-color:rgba(0,229,255,0.4);color:var(--teal);transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,229,255,0.15);}
.chip-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;}
.chip-1 .chip-dot{background:var(--pink);box-shadow:0 0 6px var(--pink);}
.chip-2 .chip-dot{background:var(--teal);box-shadow:0 0 6px var(--teal);}
.chip-3 .chip-dot{background:var(--green);box-shadow:0 0 6px var(--green);}
.chip-4 .chip-dot{background:var(--yellow);box-shadow:0 0 6px var(--yellow);}
.chip-5 .chip-dot{background:var(--purple);box-shadow:0 0 6px var(--purple);}
@keyframes chipIn{to{opacity:1;transform:scale(1);}}

/* CTA box */
.cta-box{
  text-align:center;
  padding:clamp(20px,3vh,32px) clamp(16px,3vw,32px);
  background:linear-gradient(135deg,rgba(255,77,109,0.07),rgba(0,229,255,0.05),rgba(178,75,255,0.07));
  border:1px solid rgba(255,77,109,0.25);
  border-radius:12px;
  position:relative;
  overflow:hidden;
  opacity:0;animation:fadeSlideUp 0.6s ease 1.4s both;
}
.cta-box::before{
  content:'';position:absolute;inset:0;
  background:repeating-linear-gradient(90deg,transparent,transparent 30px,rgba(255,77,109,0.02) 30px,rgba(255,77,109,0.02) 31px);
}
.cta-text{
  font-family:var(--fo);
  font-size:clamp(0.48rem,1.4vw,0.85rem);
  font-weight:700;
  letter-spacing:2px;
  color:var(--bright);
  text-transform:uppercase;
  line-height:1.8;
  position:relative;z-index:1;
  text-shadow:0 0 20px rgba(255,77,109,0.3);
}
.cta-text span{color:var(--pink);}

/* pulse ring around CTA */
.cta-ring{
  position:absolute;inset:-2px;border-radius:14px;
  border:1px solid rgba(255,77,109,0.4);
  animation:ringPulse 2.5s ease-in-out infinite;
  pointer-events:none;
}
@keyframes ringPulse{0%,100%{opacity:0.5;transform:scale(1);}50%{opacity:1;transform:scale(1.005);}}

/* ── STATS ROW ── */
.stats-row{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(160px,1fr));
  gap:clamp(10px,2vw,16px);
  margin:clamp(20px,3vh,32px) 0;
  opacity:0;animation:fadeSlideUp 0.6s ease 0.9s both;
}
.stat-card{
  background:rgba(12,14,28,0.8);
  border:1px solid var(--border);
  border-radius:10px;
  padding:clamp(14px,2vw,22px);
  text-align:center;
  position:relative;overflow:hidden;
  transition:transform 0.25s, border-color 0.25s, box-shadow 0.25s;
}
.stat-card::before{content:'';position:absolute;top:-1px;left:-1px;width:12px;height:12px;border-top:2px solid var(--c,var(--pink));border-left:2px solid var(--c,var(--pink));border-radius:10px 0 0 0;}
.stat-card:hover{transform:translateY(-4px);border-color:rgba(255,255,255,0.15);box-shadow:0 8px 30px rgba(0,0,0,0.3);}
.stat-card:nth-child(1){--c:var(--pink);}
.stat-card:nth-child(2){--c:var(--teal);}
.stat-card:nth-child(3){--c:var(--green);}
.stat-card:nth-child(4){--c:var(--yellow);}
.stat-icon svg{display:block;margin:0 auto 10px;}
.stat-label{font-family:var(--fm);font-size:clamp(0.45rem,0.8vw,0.58rem);color:rgba(200,210,230,0.5);letter-spacing:2px;text-transform:uppercase;margin-bottom:4px;}
.stat-value{font-family:var(--fo);font-size:clamp(0.55rem,1.2vw,0.75rem);color:var(--c,var(--pink));font-weight:700;letter-spacing:1px;}

/* ── PROGRESS LINE ── */
.progress-section{
  margin:clamp(20px,3vh,32px) 0;
  opacity:0;animation:fadeSlideUp 0.6s ease 1.1s both;
}
.prog-label{font-family:var(--fm);font-size:clamp(0.45rem,0.8vw,0.58rem);color:rgba(200,210,230,0.5);letter-spacing:2px;text-transform:uppercase;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;}
.prog-bar-bg{width:100%;height:6px;background:var(--border);border-radius:3px;overflow:hidden;}
.prog-bar-fill{height:100%;width:0%;border-radius:3px;background:linear-gradient(90deg,var(--pink),var(--purple),var(--teal));transition:width 1.5s cubic-bezier(0.25,0.46,0.45,0.94);}

/* ── SECTION DIVIDER ── */
.sec-div{
  display:flex;align-items:center;gap:12px;
  margin:clamp(20px,3vh,32px) 0 clamp(14px,2.5vh,22px);
}
.sec-div::before,.sec-div::after{content:'';flex:1;height:1px;background:var(--border);}
.sec-div-label{font-family:var(--fo);font-size:clamp(0.3rem,0.8vw,0.46rem);color:var(--teal);letter-spacing:3px;text-transform:uppercase;white-space:nowrap;text-shadow:0 0 10px rgba(0,229,255,0.4);}

/* ── INFO CARDS (what you'll do) ── */
.cards-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));
  gap:clamp(10px,2vw,16px);
  opacity:0;animation:fadeSlideUp 0.6s ease 0.7s both;
}
.info-card{
  background:rgba(12,14,28,0.85);
  border:1px solid var(--border);
  border-radius:10px;
  padding:clamp(14px,2vw,22px);
  position:relative;overflow:hidden;
  transition:all 0.25s;
}
.info-card::after{content:'';position:absolute;bottom:-1px;right:-1px;width:10px;height:10px;border-bottom:2px solid var(--c,var(--pink));border-right:2px solid var(--c,var(--pink));border-radius:0 0 10px 0;}
.info-card:nth-child(1){--c:var(--pink);}
.info-card:nth-child(2){--c:var(--teal);}
.info-card:nth-child(3){--c:var(--green);}
.info-card:nth-child(4){--c:var(--yellow);}
.info-card:hover{border-color:rgba(255,255,255,0.12);transform:translateY(-3px);box-shadow:0 8px 24px rgba(0,0,0,0.25);}
.card-num{font-family:var(--fo);font-size:clamp(0.3rem,0.7vw,0.44rem);color:rgba(200,210,230,0.3);letter-spacing:2px;margin-bottom:10px;}
.card-icon{margin-bottom:10px;}
.card-title{font-family:var(--fo);color:var(--c,var(--pink));font-size:clamp(0.32rem,0.8vw,0.5rem);letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;font-weight:700;}
.card-body{font-family:var(--fm);color:var(--text);font-size:clamp(0.6rem,1vw,0.72rem);line-height:1.7;}

/* ── STATUSBAR ── */
#statusbar{
  position:fixed;bottom:0;left:0;right:0;height:24px;
  background:rgba(4,6,14,0.95);
  border-top:1px solid var(--border);
  display:flex;align-items:center;padding:0 14px;gap:16px;z-index:400;
}
.sb{font-family:var(--fm);font-size:clamp(0.32rem,0.55vw,0.46rem);color:rgba(255,77,109,0.45);letter-spacing:1.5px;white-space:nowrap;}
.sb-t{color:rgba(0,229,255,0.45);}
.sb-m{flex:1;overflow:hidden;mask-image:linear-gradient(to right,transparent,black 6%,black 94%,transparent);}
#sb-scroll{display:inline-block;white-space:nowrap;font-family:var(--fm);font-size:clamp(0.32rem,0.55vw,0.46rem);color:rgba(255,77,109,0.35);letter-spacing:1.5px;animation:marquee 28s linear infinite;}
@keyframes marquee{0%{transform:translateX(100vw);}100%{transform:translateX(-100%);}}

/* ── PARTICLES ── */
.pt{position:fixed;width:2px;height:2px;border-radius:50%;pointer-events:none;z-index:1;opacity:0;animation:pfloat linear infinite;}
@keyframes pfloat{0%{transform:translateY(0) translateX(0);opacity:0;}10%{opacity:0.8;}90%{opacity:0.1;}100%{transform:translateY(-100vh) translateX(var(--dx));opacity:0;}}

/* ── KEYFRAMES ── */
@keyframes fadeSlideDown{from{opacity:0;transform:translateY(-16px);}to{opacity:1;transform:none;}}
@keyframes fadeSlideUp{from{opacity:0;transform:translateY(20px);}to{opacity:1;transform:none;}}
@keyframes fadeIn{from{opacity:0;}to{opacity:1;}}

::-webkit-scrollbar{width:4px;background:var(--dark2);}
::-webkit-scrollbar-thumb{background:var(--pink);border-radius:2px;}
::selection{background:var(--pink);color:#000;}
