<p>
<script>
/* ── CLOCK ── */
const t0 = Date.now();
setInterval(()=>{
  const s=Math.floor((Date.now()-t0)/1000);
  const h=String(Math.floor(s/3600)).padStart(2,'0');
  const m=String(Math.floor((s%3600)/60)).padStart(2,'0');
  const sc=String(s%60).padStart(2,'0');
  document.getElementById('sys-time').textContent=`SYS.TIME ${h}:${m}:${sc}`;
},1000);

/* ── GRID CANVAS ── */
const cv=document.getElementById('grid-bg');
const ctx=cv.getContext('2d');
function resizeCanvas(){cv.width=window.innerWidth;cv.height=window.innerHeight;}
resizeCanvas();
window.addEventListener('resize',resizeCanvas);
let tick=0;
function drawGrid(){
  ctx.clearRect(0,0,cv.width,cv.height);
  const sz=44;
  tick+=0.004;
  for(let x=0;x<cv.width;x+=sz){
    for(let y=0;y<cv.height;y+=sz){
      const d=Math.sqrt((x-cv.width/2)**2+(y-cv.height/2)**2);
      const wave=Math.sin(d/80-tick)*0.5+0.5;
      const alpha=wave*0.06+0.02;
      ctx.strokeStyle=`rgba(255,77,109,${alpha})`;
      ctx.lineWidth=0.5;
      ctx.strokeRect(x,y,sz,sz);
    }
  }
  requestAnimationFrame(drawGrid);
}
drawGrid();

/* ── PARTICLES ── */
for(let i=0;i<18;i++){
  const p=document.createElement('div');
  p.className='pt';
  const x=Math.random()*window.innerWidth;
  const dur=Math.random()*10+8;
  const del=Math.random()*14;
  const dx=(Math.random()-.5)*90;
  const colors=['var(--teal)','var(--pink)','var(--purple)','var(--green)'];
  p.style.cssText=`left:${x}px;bottom:0;--dx:${dx}px;animation-duration:${dur}s;animation-delay:${del}s;background:${colors[Math.floor(Math.random()*colors.length)]};`;
  document.body.appendChild(p);
}

/* ── STAGGER INTRO PARAGRAPHS ── */
const paras=document.querySelectorAll('.intro-p');
paras.forEach((p,i)=>{
  setTimeout(()=>p.classList.add('visible'), 400+i*220);
});

/* ── ANIMATE PROGRESS BAR ── */
setTimeout(()=>{
  let pct=0;
  const target=78;
  const fill=document.getElementById('prog-fill');
  const label=document.getElementById('prog-pct');
  const step=()=>{
    if(pct<target){
      pct=Math.min(pct+1,target);
      fill.style.width=pct+'%';
      label.textContent=pct+'%';
      setTimeout(step,18);
    }
  };
  step();
},1200);
</script>
