.ne-wrap{background:var(--ne-panel);border:1px solid var(--ne-border);border-radius:var(--ne-radius);padding:2rem;max-width:860px;margin:0 auto;position:relative;overflow:hidden}
.ne-wrap::before{content:'';position:absolute;top:-1px;left:-1px;width:22px;height:22px;border-top:2px solid var(--ne-pink);border-left:2px solid var(--ne-pink);border-radius:var(--ne-radius) 0 0 0}
.ne-wrap::after{content:'';position:absolute;bottom:-1px;right:-1px;width:22px;height:22px;border-bottom:2px solid var(--ne-pink);border-right:2px solid var(--ne-pink);border-radius:0 0 var(--ne-radius) 0}

/* ── BADGE ── */
.ne-badge{display:inline-flex;align-items:center;gap:6px;background:var(--ne-pink-dim);border:1px solid var(--ne-pink);border-radius:4px;padding:3px 10px;font-family:var(--ne-font-pixel);font-size:.45rem;color:var(--ne-pink);letter-spacing:1.5px;margin-bottom:1rem}
.ne-badge svg{width:10px;height:10px;stroke:var(--ne-pink)}

/* ── HEADER ── */
.ne-header{display:flex;align-items:center;gap:14px;margin-bottom:1.4rem;padding-bottom:1rem;border-bottom:1px solid var(--ne-border)}
.ne-icon-wrap{width:52px;height:52px;flex-shrink:0;background:var(--ne-pink-dim);border:1px solid var(--ne-pink);border-radius:var(--ne-radius);display:flex;align-items:center;justify-content:center;box-shadow:var(--ne-glow)}
.ne-icon-wrap svg{width:26px;height:26px;stroke:var(--ne-pink)}
.ne-title{font-family:var(--ne-font-pixel);font-size:.62rem;color:var(--ne-pink);text-shadow:var(--ne-glow);letter-spacing:2px;text-transform:uppercase;line-height:1.8}
.ne-sub{font-size:.78rem;color:rgba(200,205,216,.7);letter-spacing:1px;margin-top:4px}

/* ── PROGRESS ── */
.prog-wrap{margin-bottom:1.4rem}
.prog-info{display:flex;justify-content:space-between;align-items:center;font-family:var(--ne-font-pixel);font-size:.38rem;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px;color:var(--ne-text)}
.prog-info .hi{color:var(--ne-pink)}
.prog-bar{height:8px;background:var(--ne-border);border-radius:4px;overflow:hidden}
.prog-fill{height:100%;border-radius:4px;background:linear-gradient(90deg,var(--ne-pink),var(--ne-teal));box-shadow:0 0 8px var(--ne-pink-glow);transition:width .5s ease}
.q-dots{display:flex;gap:4px;margin-top:8px;flex-wrap:wrap}
.q-dot{width:14px;height:6px;border-radius:3px;background:var(--ne-border);transition:background .3s}
.q-dot.done-ok{background:var(--ne-green)}
.q-dot.done-ko{background:var(--ne-pink)}
.q-dot.active{background:var(--ne-yellow);box-shadow:0 0 4px rgba(255,204,0,.6)}

/* ── STAGE HEADER ── */
.stage-hdr{margin-bottom:1.2rem}
.stage-lbl{display:flex;align-items:center;gap:6px;font-family:var(--ne-font-pixel);font-size:.42rem;color:var(--ne-teal);letter-spacing:2px;text-transform:uppercase;margin-bottom:6px}
.stage-lbl svg{width:13px;height:13px;stroke:var(--ne-teal)}
.stage-title-txt{font-family:var(--ne-font-pixel);font-size:.55rem;color:var(--ne-pink);text-shadow:var(--ne-glow);letter-spacing:2px;text-transform:uppercase;line-height:1.8}

/* ── QUESTION ── */
.q-card{background:var(--ne-dark3);border:1px solid var(--ne-border);border-radius:var(--ne-radius);padding:1.4rem;animation:fadeIn .3s ease}
@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.q-num{display:flex;align-items:center;gap:6px;font-family:var(--ne-font-pixel);font-size:.38rem;color:var(--ne-teal);letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}
.q-num svg{width:12px;height:12px;stroke:var(--ne-teal)}
.q-text{font-size:.95rem;color:var(--ne-text-bright);line-height:1.6;margin-bottom:1.2rem}
.q-topic{display:inline-block;background:rgba(0,212,255,.08);border:1px solid rgba(0,212,255,.2);border-radius:3px;padding:2px 8px;font-family:var(--ne-font-pixel);font-size:.33rem;color:var(--ne-teal);letter-spacing:1.5px;margin-bottom:10px}

/* ── OPTIONS ── */
.opts{display:flex;flex-direction:column;gap:8px}
.opt-btn{background:var(--ne-dark2);border:1px solid var(--ne-border);border-radius:4px;padding:10px 14px;font-family:var(--ne-font-mono);font-size:.87rem;color:var(--ne-text);cursor:pointer;transition:all .2s;text-align:left;display:flex;align-items:center;gap:10px;line-height:1.4}
.opt-letter{font-family:var(--ne-font-pixel);font-size:.4rem;color:var(--ne-teal);flex-shrink:0;letter-spacing:1px;width:18px;text-align:center}
.opt-btn:hover:not(:disabled){border-color:var(--ne-teal);color:var(--ne-teal);background:var(--ne-teal-dim)}
.opt-btn:disabled{cursor:default}
.opt-btn.correct{border-color:var(--ne-green);background:rgba(0,255,136,.08);color:var(--ne-green)}
.opt-btn.correct .opt-letter{color:var(--ne-green)}
.opt-btn.wrong{border-color:var(--ne-pink);background:rgba(255,92,122,.08);color:var(--ne-pink);animation:shake .4s ease}
.opt-btn.wrong .opt-letter{color:var(--ne-pink)}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}

/* ── FEEDBACK ── */
.fb-block{display:none;margin-top:12px;padding:12px 14px;border-radius:4px;font-size:.85rem;line-height:1.5;animation:fadeIn .25s ease}
.fb-block.show{display:block}
.fb-block.ok{background:rgba(0,255,136,.08);border:1px solid rgba(0,255,136,.3);color:var(--ne-green)}
.fb-block.ko{background:rgba(255,92,122,.08);border:1px solid rgba(255,92,122,.3);color:var(--ne-pink)}
.fb-header{display:flex;align-items:center;gap:6px;font-family:var(--ne-font-pixel);font-size:.38rem;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px}
.fb-header svg{width:13px;height:13px}

/* ── NEXT BTN ── */
.next-btn{display:none;margin-top:1rem;background:var(--ne-pink);color:#000;border:none;border-radius:4px;padding:8px 22px;font-family:var(--ne-font-mono);font-size:.85rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;cursor:pointer;transition:all .2s;align-items:center;gap:6px}
.next-btn.show{display:inline-flex}
.next-btn svg{width:14px;height:14px;stroke:#000}
.next-btn:hover{background:var(--ne-pink-light);box-shadow:var(--ne-glow);transform:translateY(-1px)}

/* ── SCORE FLASH ── */
.score-flash{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) scale(0);background:var(--ne-dark2);border:2px solid;border-radius:var(--ne-radius);padding:20px 32px;font-family:var(--ne-font-pixel);font-size:.8rem;letter-spacing:2px;text-align:center;z-index:10000;transition:all .3s cubic-bezier(.34,1.56,.64,1);pointer-events:none}
.score-flash.show{transform:translate(-50%,-50%) scale(1)}
.score-flash.ok-flash{border-color:var(--ne-green);color:var(--ne-green);box-shadow:var(--ne-glow-green)}
.score-flash.ko-flash{border-color:var(--ne-pink);color:var(--ne-pink);box-shadow:var(--ne-glow)}

/* ── RESULTS ── */
.results-screen{text-align:center;padding:1rem 0;animation:fadeIn .5s ease}
.res-medal{margin-bottom:1rem}
.res-medal svg{width:72px;height:72px}
.res-level{font-family:var(--ne-font-pixel);font-size:.7rem;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;text-shadow:var(--ne-glow)}
.res-score{font-family:var(--ne-font-pixel);font-size:1.4rem;margin-bottom:6px;color:var(--ne-text-bright)}
.res-pct{font-family:var(--ne-font-pixel);font-size:.65rem;color:var(--ne-teal);letter-spacing:2px;margin-bottom:1.4rem}
.res-msg{font-size:.9rem;color:var(--ne-text);line-height:1.7;max-width:520px;margin:0 auto 1.4rem}
.res-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:1.4rem;max-width:500px;margin-left:auto;margin-right:auto}
.res-stat{background:var(--ne-dark3);border:1px solid var(--ne-border);border-radius:var(--ne-radius);padding:12px 8px;text-align:center}
.res-stat-val{font-family:var(--ne-font-pixel);font-size:.8rem;margin-bottom:4px}
.res-stat-lbl{font-size:.7rem;color:rgba(200,205,216,.6)}
.res-skills{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-bottom:1.4rem}
.res-skill{background:var(--ne-dark3);border:1px solid var(--ne-border);border-radius:4px;padding:4px 12px;font-family:var(--ne-font-pixel);font-size:.33rem;letter-spacing:1.5px;color:var(--ne-teal);display:flex;align-items:center;gap:5px}
.res-skill svg{width:11px;height:11px;stroke:var(--ne-teal)}
.restart-btn{background:var(--ne-pink);color:#000;border:none;border-radius:4px;padding:10px 28px;font-family:var(--ne-font-mono);font-size:.9rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;cursor:pointer;transition:all .2s;display:inline-flex;align-items:center;gap:8px}
.restart-btn svg{width:15px;height:15px;stroke:#000}
.restart-btn:hover{background:var(--ne-pink-light);box-shadow:var(--ne-glow);transform:translateY(-1px)}

/* ── STATUS BAR ── */
.ne-statusbar{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:var(--ne-dark2);border:1px solid var(--ne-border);border-radius:4px;margin-top:1.4rem;font-family:var(--ne-font-mono);font-size:.7rem;color:rgba(200,205,216,.5)}
.status-dot{width:7px;height:7px;background:var(--ne-pink);border-radius:50%;animation:blink 1.2s step-end infinite}
.status-lbl{font-family:var(--ne-font-pixel);font-size:.38rem;color:var(--ne-pink)}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}

/* ── CONFETTI ── */
.confetti-piece{position:fixed;width:8px;height:8px;border-radius:1px;pointer-events:none;z-index:9998;animation:fall linear forwards}
@keyframes fall{0%{transform:translateY(-20px) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}
</style>
<div class="ne-wrap">
<div class="ne-header">
<div class="ne-icon-wrap"><svg viewbox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 10v6M2 10l10-5 10 5-10 5-10-5z"></path><path d="M6 12v5c3 3 9 3 12 0v-5"></path></svg><br /></div>
<div>
<div class="ne-title">Evaluación Saber Pro</div>
<div class="ne-sub">Prueba final gamificada — Misión Cerebro</div>
</div>
</div>
<!-- PROGRESS -->
<div class="prog-wrap">
<div class="prog-info"><span>PROGRESO</span> <span class="hi" id="progLabel">PREGUNTA 1 DE 14</span></div>
<div class="prog-bar">
<div class="prog-fill" id="progFill" style="width: 0%;"></div>
</div>
<div class="q-dots" id="qDots"></div>
</div>
<div id="contentArea"></div>
<div class="ne-statusbar">
<div style="display: flex; align-items: center; gap: 8px;">
<div class="status-dot"><br /></div>
<span>EVALUACIÓN ACTIVA</span></div>
<span class="status-lbl" id="scoreLbl">PUNTAJE: 0 / 14</span></div>
</div>
<div class="score-flash" id="scoreFlash"></div>
<p>
<script>
// ── AUDIO ──
const AC = new (window.AudioContext || window.webkitAudioContext)();

function beep(type) {
  const o = AC.createOscillator(), g = AC.createGain();
  o.connect(g); g.connect(AC.destination);
  const now = AC.currentTime;
  if (type === 'ok') {
    o.type = 'sine';
    o.frequency.setValueAtTime(523, now);
    o.frequency.setValueAtTime(659, now + .1);
    o.frequency.setValueAtTime(784, now + .2);
    g.gain.setValueAtTime(.18, now);
    g.gain.exponentialRampToValueAtTime(.001, now + .5);
    o.start(now); o.stop(now + .5);
  } else if (type === 'ko') {
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(220, now);
    o.frequency.setValueAtTime(180, now + .1);
    g.gain.setValueAtTime(.1, now);
    g.gain.exponentialRampToValueAtTime(.001, now + .35);
    o.start(now); o.stop(now + .35);
  } else if (type === 'win') {
    const freqs = [523,659,784,1047];
    freqs.forEach((f, i) => {
      const oo = AC.createOscillator(), gg = AC.createGain();
      oo.connect(gg); gg.connect(AC.destination);
      oo.type = 'sine'; oo.frequency.value = f;
      gg.gain.setValueAtTime(.15, now + i*.12);
      gg.gain.exponentialRampToValueAtTime(.001, now + i*.12 + .4);
      oo.start(now + i*.12); oo.stop(now + i*.12 + .4);
    });
  }
}

// ── QUESTIONS ──
const QS = [
  {topic:'CEREBRO',q:'¿Cuál es la función principal de las neuronas en el sistema nervioso?',opts:['Producir energía para los músculos','Transmitir señales eléctricas y químicas entre células','Regular la temperatura corporal','Filtrar toxinas del organismo'],ans:1,fb:'Las neuronas son las células del sistema nervioso especializadas en transmitir información mediante impulsos eléctricos y señales químicas (neurotransmisores) a través de sinapsis.'},
  {topic:'CEREBRO',q:'¿Qué estructura cerebral es responsable del equilibrio y la coordinación motora?',opts:['Lóbulo frontal','Hipocampo','Cerebelo','Amígdala'],ans:2,fb:'El cerebelo, ubicado en la parte posterior del encéfalo, regula el equilibrio, la coordinación de movimientos y el tono muscular. Sin él, los movimientos serían torpes e imprecisos.'},
  {topic:'CEREBRO',q:'El tronco encefálico controla principalmente:',opts:['El aprendizaje y la memoria declarativa','Los procesos automáticos como la respiración, el ritmo cardíaco y el sueño','Las emociones y el procesamiento del miedo','El lenguaje y la comprensión verbal'],ans:1,fb:'El tronco encefálico (bulbo raquídeo, protuberancia y mesencéfalo) regula funciones vitales automáticas como la respiración, el ritmo cardíaco, la presión arterial y los ciclos de sueño-vigilia.'},
  {topic:'APRENDIZAJE',q:'¿Qué proceso cerebral ocurre cuando practicamos una habilidad repetidamente y esta se vuelve automática?',opts:['Consolidación sináptica','Mielinización y fortalecimiento de rutas neuronales','Inhibición de la corteza prefrontal','Activación de la amígdala'],ans:1,fb:'La práctica repetida fortalece las conexiones sinápticas y promueve la mielinización (revestimiento de los axones), lo que hace que los circuitos neuronales funcionen más rápido y de forma automática.'},
  {topic:'MEMORIA',q:'¿Qué tipo de memoria almacena información durante años y puede recuperarse consciente-mente?',opts:['Memoria sensorial','Memoria de trabajo','Memoria a largo plazo','Memoria ecoica'],ans:2,fb:'La memoria a largo plazo almacena información de forma relativamente permanente. Incluye la memoria explícita (hechos y episodios) y la implícita (habilidades y hábitos).'},
  {topic:'MEMORIA',q:'¿Qué región cerebral es clave para consolidar nuevos recuerdos a largo plazo?',opts:['Cerebelo','Corteza motora','Hipocampo','Tálamo'],ans:2,fb:'El hipocampo, ubicado en el lóbulo temporal, es fundamental para la consolidación de nuevos recuerdos episódicos y declarativos, transfiriéndolos para almacenamiento en la corteza cerebral.'},
  {topic:'ATENCIÓN',q:'La atención selectiva permite:',opts:['Recordar eventos del pasado con detalle','Enfocarse en estímulos relevantes ignorando distracciones','Resolver problemas matemáticos complejos','Aprender idiomas sin esfuerzo'],ans:1,fb:'La atención selectiva es la capacidad de concentrarse en información relevante mientras se filtra o ignora lo irrelevante. Es gestionada principalmente por la corteza prefrontal y los lóbulos parietales.'},
  {topic:'ATENCIÓN',q:'¿Cuánto tiempo tarda en promedio el cerebro en recuperar la concentración plena después de una interrupción?',opts:['2 minutos','10 minutos','23 minutos','45 minutos'],ans:2,fb:'Investigaciones muestran que tras una distracción (como revisar el teléfono), la recuperación del estado de concentración plena tarda en promedio 23 minutos. Por eso las interrupciones frecuentes son tan costosas cognitivamente.'},
  {topic:'EMOCIONES',q:'¿Qué neurotransmisor se libera principalmente cuando experimentamos alegría y refuerza el aprendizaje?',opts:['Cortisol','Melatonina','Dopamina','Histamina'],ans:2,fb:'La dopamina es el principal neurotransmisor asociado a la recompensa y el placer. Al liberarse durante experiencias positivas, refuerza los circuitos cerebrales involucrados, favoreciendo la motivación y el aprendizaje.'},
  {topic:'EMOCIONES',q:'El estrés crónico afecta el aprendizaje principalmente porque:',opts:['Reduce la producción de dopamina permanentemente','El exceso de cortisol interfiere con el hipocampo y deteriora la memoria','Aumenta el volumen del cerebelo','Bloquea la producción de melatonina'],ans:1,fb:'El cortisol, la hormona del estrés, en niveles elevados y sostenidos daña neuronas del hipocampo, dificultando la consolidación de nuevos recuerdos y el aprendizaje efectivo.'},
  {topic:'SUEÑO',q:'Durante el sueño REM, el cerebro realiza principalmente:',opts:['Reparación muscular y liberación de hormona de crecimiento','Procesamiento emocional, consolidación de memorias procedurales y sueños vívidos','Detoxificación del sistema linfático cerebral','Regulación de la temperatura corporal'],ans:1,fb:'Durante el sueño REM (movimiento ocular rápido), el cerebro está altamente activo: procesa las emociones del día, consolida memorias de habilidades y produce los sueños más intensos.'},
  {topic:'SUEÑO',q:'¿Cuántas horas de sueño necesitan aproximadamente los adolescentes para un óptimo rendimiento cerebral?',opts:['4 a 5 horas','6 horas exactas','8 a 10 horas','12 o más horas'],ans:2,fb:'Los adolescentes necesitan entre 8 y 10 horas de sueño porque sus cerebros están en un período crítico de desarrollo. Durante ese tiempo se consolidan aprendizajes y se fortalecen conexiones neuronales.'},
  {topic:'HÁBITOS',q:'¿Por qué la técnica de repetición espaciada es más efectiva que estudiar todo en una sola sesión?',opts:['Porque permite aprender más rápido en menos tiempo','Porque genera intervals de olvido parcial que fortalecen la recuperación neural','Porque reduce la necesidad de dormir','Porque activa el cerebelo durante el aprendizaje'],ans:1,fb:'La repetición espaciada aprovecha la "curva del olvido" de Ebbinghaus: revisar el material en intervalos crecientes fortalece las conexiones sinápticas cada vez que se recupera la información, mejorando la retención a largo plazo.'},
  {topic:'HÁBITOS',q:'¿Cuál de las siguientes acciones tiene mayor impacto positivo inmediato en el rendimiento cognitivo?',opts:['Estudiar con música de fondo animada','Memorizar la información leyéndola en voz alta 10 veces','Dormir 8 horas tras estudiar y autoevaluarse al día siguiente','Estudiar 6 horas seguidas sin descanso'],ans:2,fb:'Combinar el sueño adecuado (para consolidar) con la autoevaluación activa (para recuperar) es la estrategia con mayor respaldo neurocientífico para optimizar el aprendizaje y la retención a largo plazo.'},
];

let qIdx=0, score=0, answered=false;

function initDots() {
  const d = document.getElementById('qDots');
  d.innerHTML = QS.map((_,i) => `<div class="q-dot${i===0?' active':''}" id="dot${i}"></div>`).join('');
}

function updateProg() {
  const pct = (qIdx / QS.length) * 100;
  document.getElementById('progFill').style.width = pct + '%';
  document.getElementById('progLabel').textContent = `PREGUNTA ${qIdx+1} DE ${QS.length}`;
  document.getElementById('scoreLbl').textContent = `PUNTAJE: ${score} / ${QS.length}`;
  document.querySelectorAll('.q-dot').forEach((d,i) => {
    d.classList.remove('active');
    if (i === qIdx) d.classList.add('active');
  });
}

function flash(type, txt) {
  const f = document.getElementById('scoreFlash');
  f.textContent = txt;
  f.className = 'score-flash show ' + (type==='ok'?'ok-flash':'ko-flash');
  setTimeout(() => { f.className = 'score-flash'; }, 1000);
}

function confetti() {
  const colors = ['#ff5c7a','#00d4ff','#ffcc00','#00ff88','#b388ff'];
  for (let i = 0; i < 60; i++) {
    const el = document.createElement('div');
    el.className = 'confetti-piece';
    el.style.cssText = `left:${Math.random()*100}vw;background:${colors[Math.floor(Math.random()*colors.length)]};animation-duration:${1.5+Math.random()*2}s;animation-delay:${Math.random()*.5}s;`;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 3500);
  }
}

function renderQ() {
  if (qIdx >= QS.length) { renderResults(); return; }
  answered = false;
  updateProg();
  const q = QS[qIdx];
  const letters = ['A','B','C','D'];
  document.getElementById('contentArea').innerHTML = `
    <div class="stage-hdr">
      <div class="stage-lbl">
        <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg>
        EVALUACIÓN SABER PRO
      </div>
      <div class="stage-title-txt">Pregunta ${qIdx+1} de ${QS.length}</div>
    </div>
    <div class="q-card">
      <div class="q-topic">${q.topic}</div>
      <div class="q-num">
        <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16" stroke-width="3"/></svg>
        PREGUNTA ${qIdx+1}
      </div>
      <div class="q-text">${q.q}</div>
      <div class="opts">
        ${q.opts.map((o,i) => `<button class="opt-btn" onclick="answer(${i})" id="opt${i}"><span class="opt-letter">${letters[i]}</span>${o}</button>`).join('')}
      </div>
      <div class="fb-block" id="fb"></div>
      <button class="next-btn" id="nextBtn" onclick="nextQ()">
        <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
        ${qIdx+1 < QS.length ? 'Siguiente pregunta' : 'Ver resultados'}
      </button>
    </div>`;
}

function answer(chosen) {
  if (answered) return;
  answered = true;
  const q = QS[qIdx];
  document.querySelectorAll('.opt-btn').forEach(b => b.disabled = true);
  const fb = document.getElementById('fb');
  const dot = document.getElementById('dot' + qIdx);
  if (chosen === q.ans) {
    document.getElementById('opt' + chosen).classList.add('correct');
    fb.innerHTML = `<div class="fb-header" style="color:var(--ne-green)"><svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>¡CORRECTO!</div>${q.fb}`;
    fb.className = 'fb-block ok show';
    dot.classList.remove('active'); dot.classList.add('done-ok');
    score++;
    flash('ok', '✓ +1 PUNTO');
    beep('ok');
  } else {
    document.getElementById('opt' + chosen).classList.add('wrong');
    document.getElementById('opt' + q.ans).classList.add('correct');
    fb.innerHTML = `<div class="fb-header" style="color:var(--ne-pink)"><svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-pink)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>INCORRECTO</div>${q.fb}`;
    fb.className = 'fb-block ko show';
    dot.classList.remove('active'); dot.classList.add('done-ko');
    flash('ko', '✗ SIGUE APRENDIENDO');
    beep('ko');
  }
  document.getElementById('scoreLbl').textContent = `PUNTAJE: ${score} / ${QS.length}`;
  document.getElementById('nextBtn').classList.add('show');
}

function nextQ() { qIdx++; renderQ(); }

function renderResults() {
  document.getElementById('progFill').style.width = '100%';
  document.getElementById('progLabel').textContent = 'EVALUACIÓN COMPLETADA';
  const pct = Math.round(score / QS.length * 100);
  let medal, level, color, msg;
  if (pct >= 85) {
    medal = `<svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-yellow)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9H4a2 2 0 0 1-2-2V5h4"/><path d="M18 9h2a2 2 0 0 0 2-2V5h-4"/><path d="M6 5h12v5a6 6 0 0 1-12 0V5z"/><line x1="12" y1="15" x2="12" y2="22"/><line x1="8" y1="22" x2="16" y2="22"/></svg>`;
    level = 'Maestro del Cerebro'; color = 'var(--ne-yellow)';
    msg = '¡Extraordinario! Demostraste un dominio excepcional de la neurociencia del aprendizaje. Tu cerebro está optimizado para seguir aprendiendo.';
    confetti(); beep('win');
  } else if (pct >= 65) {
    medal = `<svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-teal)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>`;
    level = 'Explorador de la Mente'; color = 'var(--ne-teal)';
    msg = '¡Muy bien! Tienes una sólida comprensión del cerebro y el aprendizaje. Repasa los temas donde tuviste dudas para alcanzar la maestría.';
    beep('win');
  } else {
    medal = `<svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-pink)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
    level = 'Aprendiz Neurocientífico'; color = 'var(--ne-pink)';
    msg = 'Buen intento. El aprendizaje es un proceso continuo. Revisa el material de las misiones y vuelve a intentarlo: ¡puedes lograrlo!';
  }
  const topics = [...new Set(QS.map(q => q.topic))];
  document.getElementById('contentArea').innerHTML = `
    <div class="results-screen">
      <div class="res-medal" style="color:${color}">${medal}</div>
      <div class="res-level" style="color:${color}">${level}</div>
      <div class="res-score">${score} / ${QS.length}</div>
      <div class="res-pct">${pct}% de dominio</div>
      <div class="res-msg">${msg}</div>
      <div class="res-stats">
        <div class="res-stat"><div class="res-stat-val" style="color:var(--ne-green)">${score}</div><div class="res-stat-lbl">Correctas</div></div>
        <div class="res-stat"><div class="res-stat-val" style="color:var(--ne-pink)">${QS.length-score}</div><div class="res-stat-lbl">Incorrectas</div></div>
        <div class="res-stat"><div class="res-stat-val" style="color:var(--ne-teal)">${pct}%</div><div class="res-stat-lbl">Dominio</div></div>
      </div>
      <div class="res-skills">
        ${topics.map(t=>`<div class="res-skill"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>${t}</div>`).join('')}
      </div>
      <button class="restart-btn" onclick="restart()">
        <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
        Intentar de nuevo
      </button>
    </div>`;
  document.getElementById('scoreLbl').textContent = `${pct}% COMPLETADO`;
}

function restart() { qIdx=0; score=0; initDots(); renderQ(); }

initDots(); renderQ();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

