.order-item.over{border-color:var(--ne-yellow);background:rgba(255,204,0,.05)}
.order-item.correct-pos{border-color:var(--ne-green);background:rgba(0,255,136,.06);cursor:default;color:var(--ne-green)}
.order-item.wrong-pos{border-color:var(--ne-pink);background:rgba(255,92,122,.06);color:var(--ne-pink)}

/* ── STAGE 4: CASE ── */
.case-scenario{font-size:.92rem;color:var(--ne-text-bright);line-height:1.7;font-style:italic;border-left:3px solid var(--ne-yellow);padding-left:12px;margin-bottom:1rem}
.case-q-title{display:flex;align-items:center;gap:6px;font-family:var(--ne-font-pixel);font-size:.4rem;color:var(--ne-yellow);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px}
.case-q-title svg{width:12px;height:12px;stroke:var(--ne-yellow)}
.case-opts{display:flex;flex-direction:column;gap:8px}
.case-opt{background:var(--ne-dark2);border:1px solid var(--ne-border);border-radius:4px;padding:10px 14px;font-size:.87rem;color:var(--ne-text);cursor:pointer;transition:all .2s;text-align:left;display:flex;align-items:flex-start;gap:8px;line-height:1.4}
.case-opt svg{width:14px;height:14px;stroke:var(--ne-text);flex-shrink:0;margin-top:2px}
.case-opt:hover:not(:disabled){border-color:var(--ne-teal);color:var(--ne-teal)}
.case-opt:hover:not(:disabled) svg{stroke:var(--ne-teal)}
.case-opt:disabled{cursor:default}
.case-opt.correct{border-color:var(--ne-green);background:rgba(0,255,136,.08);color:var(--ne-green)}
.case-opt.correct svg{stroke:var(--ne-green)}
.case-opt.wrong{border-color:var(--ne-pink);background:rgba(255,92,122,.08);color:var(--ne-pink);animation:shake .35s ease}
.case-opt.wrong svg{stroke:var(--ne-pink)}

/* ── FEEDBACK ── */
.fb-block{display:none;margin-top:12px;padding:12px 14px;border-radius:4px;font-size:.85rem;line-height:1.5;animation:fadeIn .25s ease}
.fb-block.show{display:block}
.fb-block.ok{background:rgba(0,255,136,.08);border:1px solid rgba(0,255,136,.3);color:var(--ne-green)}
.fb-block.ko{background:rgba(255,92,122,.08);border:1px solid rgba(255,92,122,.3);color:var(--ne-pink)}
.fb-block.neutral{background:rgba(0,212,255,.08);border:1px solid rgba(0,212,255,.2);color:var(--ne-teal)}

/* ── BUTTONS ── */
.act-btn{background:var(--ne-teal);color:#000;border:none;border-radius:4px;padding:8px 20px;font-family:var(--ne-font-mono);font-size:.85rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;cursor:pointer;transition:all .2s;display:inline-flex;align-items:center;gap:6px;margin-top:1rem}
.act-btn svg{width:14px;height:14px;stroke:#000}
.act-btn:hover{background:#33e8ff;box-shadow:var(--ne-glow-teal);transform:translateY(-1px)}
.act-btn.pink{background:var(--ne-pink)}
.act-btn.pink:hover{background:var(--ne-pink-light);box-shadow:var(--ne-glow)}
.act-btn.green{background:var(--ne-green)}
.act-btn.green:hover{background:#33ffaa;box-shadow:var(--ne-glow-green)}
.act-btn.secondary{background:var(--ne-dark2);color:var(--ne-text);border:1px solid var(--ne-border)}
.act-btn.secondary svg{stroke:var(--ne-text)}
.act-btn.secondary:hover{border-color:var(--ne-teal);color:var(--ne-teal);box-shadow:none;transform:none}
.btn-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:1rem}

/* ── RESULTS ── */
.results-screen{text-align:center;padding:1rem 0;animation:fadeIn .5s ease}
.res-medal svg{width:72px;height:72px}
.res-level{font-family:var(--ne-font-pixel);font-size:.68rem;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;margin-top:1rem}
.res-score{font-family:var(--ne-font-pixel);font-size:1.3rem;margin-bottom:6px;color:var(--ne-text-bright)}
.res-pct{font-family:var(--ne-font-pixel);font-size:.62rem;color:var(--ne-teal);letter-spacing:2px;margin-bottom:1.4rem}
.res-msg{font-size:.9rem;color:var(--ne-text);line-height:1.7;max-width:520px;margin:0 auto 1.4rem}
.res-stages{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-bottom:1.4rem}
.res-stage-card{background:var(--ne-dark3);border:1px solid var(--ne-border);border-radius:var(--ne-radius);padding:10px 14px;text-align:center;min-width:110px}
.res-stage-val{font-family:var(--ne-font-pixel);font-size:.65rem;margin-bottom:4px}
.res-stage-lbl{font-size:.7rem;color:rgba(200,205,216,.6)}

/* ── STATUS ── */
.ne-statusbar{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:var(--ne-dark2);border:1px solid var(--ne-border);border-radius:4px;margin-top:1.4rem;font-family:var(--ne-font-mono);font-size:.7rem;color:rgba(200,205,216,.5)}
.status-dot{width:7px;height:7px;background:var(--ne-teal);border-radius:50%;animation:blink 1.2s step-end infinite}
.status-lbl{font-family:var(--ne-font-pixel);font-size:.38rem;color:var(--ne-teal)}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
.confetti-piece{position:fixed;width:8px;height:8px;border-radius:1px;pointer-events:none;z-index:9998;animation:fall linear forwards}
@keyframes fall{0%{transform:translateY(-20px) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}
</style>
