<p>
<script>
// ── AUDIO ──
const AC = new (window.AudioContext || window.webkitAudioContext)();
function beepWin() {
  const now = AC.currentTime;
  [523,659,784,1047,1319].forEach((f,i)=>{
    const o=AC.createOscillator(),g=AC.createGain();
    o.connect(g); g.connect(AC.destination);
    o.type='sine'; o.frequency.value=f;
    g.gain.setValueAtTime(.12,now+i*.1);
    g.gain.exponentialRampToValueAtTime(.001,now+i*.1+.45);
    o.start(now+i*.1); o.stop(now+i*.1+.45);
  });
}

// ── CONFETTI ──
function confetti() {
  const cols=['#ff5c7a','#00d4ff','#ffcc00','#00ff88','#b388ff'];
  for(let i=0;i<80;i++){
    const el=document.createElement('div');
    el.className='confetti-piece';
    el.style.cssText=`left:${Math.random()*100}vw;background:${cols[Math.floor(Math.random()*cols.length)]};animation-duration:${1.5+Math.random()*2.5}s;animation-delay:${Math.random()*.8}s;`;
    document.body.appendChild(el);
    setTimeout(()=>el.remove(),4000);
  }
}

// ── INIT ──
window.addEventListener('load', () => {
  setTimeout(()=>{ confetti(); beepWin(); }, 600);
  const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const d=new Date();
  document.getElementById('certDate').textContent=`Expedido el ${d.getDate()} de ${months[d.getMonth()]} de ${d.getFullYear()}`;
});

// ── CERTIFICATE ──
function showCertificate() {
  const cert=document.getElementById('certificate');
  const btns=document.getElementById('certBtns');
  cert.classList.add('visible');
  btns.style.display='flex';
  setTimeout(()=>{ confetti(); beepWin(); }, 200);
  cert.scrollIntoView({behavior:'smooth',block:'center'});
}
function hideCertificate() {
  document.getElementById('certificate').classList.remove('visible');
  document.getElementById('certBtns').style.display='none';
}

// ── REFLECTION ──
function saveReflection(btn) {
  const ta=btn.previousElementSibling;
  if(ta.value.trim().length<10){ta.style.borderColor='var(--ne-pink)';return;}
  const msg=document.getElementById('reflMsg');
  msg.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="var(--ne-green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:15px;height:15px"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg> ¡Reflexión guardada! Llevas contigo el aprendizaje más importante: conocerte a ti mismo.';
  msg.style.display='flex';
  btn.disabled=true; btn.style.opacity='.5';
}
</script>
