  #ne-root *, #ne-root *::before, #ne-root *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  /* fondo de grid — position:absolute dentro del root, NO fixed */
  #ne-grid {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    z-index: 0;
    pointer-events: none;
  }

  /* scanline overlay — position:absolute */
  #ne-root::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 9;
    background: repeating-linear-gradient(
      0deg,
      transparent, transparent 3px,
      rgba(0,0,0,0.05) 3px, rgba(0,0,0,0.05) 4px
    );
    opacity: 0.35;
  }

  /* ── TOPBAR ── */
  #ne-topbar {
    position: relative;
    z-index: 10;
    background: rgba(4,6,14,0.95);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255,77,109,0.35);
    box-shadow: 0 0 30px rgba(255,77,109,0.1);
    display: flex;
    align-items: center;
    padding: 0 clamp(12px, 2vw, 24px);
    height: 52px;
    gap: 14px;
  }

  .ne-dot {
    width: 8px; height: 8px;
    background: var(--pink);
    border-radius: 50%;
    flex-shrink: 0;
    animation: ne-blink 1.4s step-end infinite;
    box-shadow: 0 0 8px var(--pink);
  }

  .ne-logo {
    font-family: var(--fo);
    color: var(--pink);
    font-size: clamp(0.5rem, 1.4vw, 0.78rem);
    letter-spacing: 4px;
    font-weight: 900;
    text-transform: uppercase;
    text-shadow: 0 0 16px rgba(255,77,109,0.5);
    flex-shrink: 0;
  }

  .ne-sep {
    width: 1px; height: 26px;
    background: var(--border);
    flex-shrink: 0;
  }

  .ne-url {
    font-family: var(--fm);
    color: rgba(0,229,255,0.6);
    font-size: clamp(0.48rem, 1vw, 0.65rem);
    letter-spacing: 1px;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .ne-url span { color: var(--teal); text-shadow: 0 0 8px rgba(0,229,255,0.4); }

  #ne-time {
    font-family: var(--fm);
    color: rgba(0,229,255,0.55);
    font-size: clamp(0.44rem, 0.9vw, 0.6rem);
    letter-spacing: 2px;
    flex-shrink: 0;
  }

  .ne-btn {
    flex-shrink: 0;
    padding: 5px 14px;
    border-radius: 4px;
    background: rgba(255,77,109,0.1);
    border: 1px solid rgba(255,77,109,0.35);
    color: var(--pink);
    font-family: var(--fo);
    font-size: clamp(0.3rem, 0.7vw, 0.44rem);
    letter-spacing: 2px;
    cursor: pointer;
    font-weight: 700;
    text-transform: uppercase;
    transition: all 0.2s;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .ne-btn:hover {
    background: rgba(255,77,109,0.2);
    box-shadow: 0 0 16px rgba(255,77,109,0.2);
  }

  /* ── WRAP / FRAME ── */
  #ne-wrap {
    position: relative;
    z-index: 10;
    display: flex;
    justify-content: center;
    padding: 12px 16px 0;
  }

  #ne-shell {
    position: relative;
    overflow: hidden;
    width: min(1200px, 100%);
    /* Altura fija — suficiente para ver el contenido completo */
    height: 850px;
    border: 1px solid rgba(0,229,255,0.25);
    border-radius: 10px;
    box-shadow:
      0 0 40px rgba(0,229,255,0.08),
      0 0 80px rgba(255,77,109,0.06);
  }

  /* borde animado top */
  #ne-shell::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    z-index: 20;
    background: linear-gradient(90deg, transparent, var(--pink), var(--teal), var(--purple), transparent);
    background-size: 300% 100%;
    animation: ne-scanH 3s linear infinite;
    border-radius: 10px 10px 0 0;
  }

  @keyframes ne-scanH {
    0%   { background-position: -100% 0; }
    100% { background-position: 200% 0; }
  }

  #ne-shell iframe {
    width: 100%;
    height: 100%;
    border: none;
    display: block;
    border-radius: 10px;
    opacity: 0;
    transition: opacity 0.6s ease;
  }
  #ne-shell iframe.loaded { opacity: 1; }

  /* ── LOADING OVERLAY ── */
  #ne-loading {
    position: absolute;
    inset: 0;
    z-index: 50;
    background: var(--dark);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 20px;
    transition: opacity 0.5s ease;
    border-radius: 10px;
  }
  #ne-loading.hide { opacity: 0; pointer-events: none; }

  .ne-ring {
    width: 64px; height: 64px;
    border-radius: 50%;
    border: 2px solid var(--border);
    border-top: 2px solid var(--pink);
    border-right: 2px solid var(--teal);
    animation: ne-spin 1s linear infinite;
  }
  @keyframes ne-spin { to { transform: rotate(360deg); } }

  .ne-load-text {
    font-family: var(--fo);
    color: var(--pink);
    font-size: clamp(0.4rem, 1vw, 0.58rem);
    letter-spacing: 3px;
    text-transform: uppercase;
    text-shadow: 0 0 12px rgba(255,77,109,0.4);
  }
  .ne-load-sub {
    font-family: var(--fm);
    color: rgba(0,229,255,0.5);
    font-size: clamp(0.4rem, 0.8vw, 0.54rem);
    letter-spacing: 2px;
    animation: ne-blink 1.8s step-end infinite;
  }
  .ne-bar-bg {
    width: 220px; height: 3px;
    background: var(--border);
    border-radius: 2px;
    overflow: hidden;
  }
  .ne-bar-fill {
    height: 100%; width: 0%;
    background: linear-gradient(90deg, var(--pink), var(--teal));
    border-radius: 2px;
    transition: width 0.3s ease;
  }

  /* ── STATUSBAR ── */
  #ne-status {
    position: relative;
    z-index: 10;
    height: 24px;
    background: rgba(4,6,14,0.95);
    border-top: 1px solid var(--border);
    display: flex;
    align-items: center;
    padding: 0 14px;
    gap: 16px;
    margin-top: 0;
  }

  .ne-sb {
    font-family: var(--fm);
    font-size: clamp(0.3rem, 0.5vw, 0.42rem);
    color: rgba(255,77,109,0.4);
    letter-spacing: 1.5px;
    white-space: nowrap;
  }
  .ne-sb-t { color: rgba(0,229,255,0.4); }
  .ne-sb-m {
    flex: 1;
    overflow: hidden;
    mask-image: linear-gradient(to right, transparent, black 5%, black 95%, transparent);
  }
  #ne-marquee {
    display: inline-block;
    white-space: nowrap;
    font-family: var(--fm);
    font-size: clamp(0.3rem, 0.5vw, 0.42rem);
    color: rgba(255,77,109,0.3);
    letter-spacing: 1.5px;
    animation: ne-marquee 30s linear infinite;
  }
  @keyframes ne-marquee {
    0%   { transform: translateX(100vw); }
    100% { transform: translateX(-100%); }
  }
  .ne-live {
    display: flex; align-items: center; gap: 5px;
    color: rgba(0,255,157,0.6);
  }
  .ne-live-dot {
    width: 5px; height: 5px;
    background: var(--green);
    border-radius: 50%;
    box-shadow: 0 0 6px var(--green);
    animation: ne-blink 1.2s step-end infinite;
  }

  @keyframes ne-blink {
    0%, 100% { opacity: 1; }
    50%       { opacity: 0; }
  }

  /* ── PARTÍCULAS ── */
  .ne-pt {
    position: absolute;
    width: 2px; height: 2px;
    border-radius: 50%;
    pointer-events: none;
    z-index: 1;
    opacity: 0;
    animation: ne-pfloat linear infinite;
  }
  @keyframes ne-pfloat {
    0%   { transform: translateY(0); opacity: 0; }
    10%  { opacity: 0.7; }
    90%  { opacity: 0.05; }
    100% { transform: translateY(-852px) translateX(var(--dx)); opacity: 0; }
  }

  /* responsive */
  @media (max-width: 600px) {
    #ne-shell { height: 600px; }
  }
</style>
