<script>
(function() {
  /* CLOCK */
  const t0 = Date.now();
  setInterval(() => {
    const s = Math.floor((Date.now() - t0) / 1000);
    const el = document.getElementById('ne-time');
    if (el) el.textContent =
      [Math.floor(s/3600), Math.floor((s%3600)/60), s%60]
        .map(n => String(n).padStart(2,'0')).join(':');
  }, 1000);

  /* GRID CANVAS — dibuja solo dentro del root */
  const root = document.getElementById('ne-root');
  const cv   = document.getElementById('ne-grid');
  const ctx  = cv.getContext('2d');

  function resizeGrid() {
    cv.width  = root.offsetWidth;
    cv.height = root.offsetHeight;
  }
  resizeGrid();
  window.addEventListener('resize', resizeGrid);

  let tk = 0;
  (function draw() {
    ctx.clearRect(0, 0, cv.width, cv.height);
    tk += 0.003;
    const sz = 48;
    for (let x = 0; x < cv.width; x += sz)
      for (let y = 0; y < cv.height; y += sz) {
        const d = Math.sqrt((x - cv.width/2)**2 + (y - cv.height/2)**2);
        const a = (Math.sin(d/90 - tk)*0.5 + 0.5)*0.055 + 0.015;
        ctx.strokeStyle = `rgba(0,229,255,${a})`;
        ctx.lineWidth = 0.4;
        ctx.strokeRect(x, y, sz, sz);
      }
    requestAnimationFrame(draw);
  })();

  /* LOADING BAR */
  const fill = document.getElementById('ne-fill');
  let pct = 0;
  const barStep = () => {
    if (pct < 90) {
      pct += Math.random()*4 + 1;
      if (pct > 90) pct = 90;
      fill.style.width = pct + '%';
      setTimeout(barStep, 120 + Math.random()*80);
    }
  };
  barStep();

  /* IFRAME LOAD */
  const frame   = document.getElementById('ne-frame');
  const loading = document.getElementById('ne-loading');
  frame.addEventListener('load', () => {
    fill.style.width = '100%';
    setTimeout(() => {
      loading.classList.add('hide');
      frame.classList.add('loaded');
      setTimeout(() => loading.style.display = 'none', 600);
    }, 400);
  });
  /* Fallback */
  setTimeout(() => {
    if (!frame.classList.contains('loaded')) {
      fill.style.width = '100%';
      loading.classList.add('hide');
      frame.classList.add('loaded');
    }
  }, 6000);

  /* PARTÍCULAS — dentro del root, no en body */
  const colors = ['var(--teal)','var(--pink)','var(--purple)','var(--green)'];
  for (let i = 0; i < 14; i++) {
    const p = document.createElement('div');
    p.className = 'ne-pt';
    p.style.cssText = `left:${Math.random()*100}%;bottom:0;--dx:${(Math.random()-.5)*80}px;`
      + `animation-duration:${Math.random()*10+8}s;animation-delay:${Math.random()*16}s;`
      + `background:${colors[Math.floor(Math.random()*4)]};`;
    root.appendChild(p);
  }
})();
</script>
