<script>
  // Animate member cards on scroll
  const cards = document.querySelectorAll('.member-card');
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        setTimeout(() => {
          entry.target.classList.add('visible');
          entry.target.style.animationDelay = (i * 0.1) + 's';
        }, i * 100);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });

  cards.forEach(card => observer.observe(card));

  // Animate progress bars
  setTimeout(() => {
    const p1 = document.getElementById('progress1');
    const p2 = document.getElementById('progress2');
    if (p1) p1.style.width = '100%';
    if (p2) p2.style.width = '75%';
  }, 800);

  // Stagger info-item animations
  document.querySelectorAll('.info-item').forEach((el, i) => {
    el.style.animationDelay = (i * 0.08) + 's';
    el.style.animation = 'float-in 0.5s ease both';
    el.style.animationDelay = (0.2 + i * 0.08) + 's';
  });

  // Glitch effect on mission title hover
  const title = document.querySelector('.mission-title');
  if (title) {
    title.addEventListener('mouseenter', () => {
      title.style.animation = 'glitch 0.4s steps(1) infinite, rgb-shift 4s ease infinite';
    });
    title.addEventListener('mouseleave', () => {
      title.style.animation = 'rgb-shift 4s ease infinite';
    });
  }
</script>
